DG.put("ath-pakhyaan-charitr-likhyate/217",{"n":217,"title":null,"title_roman":null,"page":1879,"blocks":[{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1879,"meaning_status":"draft","meaning_pa":"ਦੋਹਰਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[1],"number_text":"੧।","page":1879,"lines":[{"gurmukhi":"ਫੈਲਕੂਸ ਪਾਤਿਸਾਹ ਕੇ ਸੂਰ ਸਿਕੰਦਰ ਪੂਤ।","roman":"Phailkoos paatisaah ke soor sikandar poot |","meaning_en":"The warrior Sikandar was the son of King Failkus,","page":1879,"meaning_status":"draft","note":"ਫੈਲਕੂਸ: Philip; ਸਿਕੰਦਰ: Alexander.","meaning_pa":"ਫੈਲਕੂਸ ਬਾਦਸ਼ਾਹ ਦਾ ਸਿਕੰਦਰ ਨਾ ਦਾ ਸ਼ੂਰਵੀਰ ਪੁੱਤਰ ਸੀ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਸੰਬਰਾਰਿ ਲਾਜਤ ਨਿਰਖਿ ਸੀਰਤਿ ਸੂਰਤਿ ਸਪੂਤ। ੧।","roman":"Sanbraari laajat nirkhi seerti soorti sapoot | 1 |","meaning_en":"a worthy son, at the sight of whose character and form the foe of Sambar felt shame.","page":1879,"meaning_status":"draft","note":"ਸੰਬਰਾਰਿ: 'enemy of Sambar', Kamdev, the god of love.","meaning_pa":"ਉਸ ਸੁਪੁੱਤਰ ਦੀ ਸੀਰਤ ਅਤੇ ਸੂਰਤ ਨੂੰ ਵੇਖ ਕੇ ਕਾਮ ਦੇਵ ('ਸੰਬਰਾਰਿ') ਵੀ ਸ਼ਰਮਿੰਦਾ ਹੁੰਦਾ ਸੀ ॥੧॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1879,"meaning_status":"draft","meaning_pa":"ਚੌਪਈ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[2],"number_text":"੨।","page":1879,"lines":[{"gurmukhi":"ਰਾਜ ਸਾਜ ਜਬ ਹੀ ਤਿਨ ਧਰਿਯੋ। ਪ੍ਰਥਮ ਜੰਗ ਜੰਗਿਰ ਸੌ ਕਰਿਯੋ।","roman":"Raaj saaj jab hee tin dhariyo | pratham jang jangir sau kariyo |","meaning_en":"As soon as he took up the state of kingship, he first made war on Jangir.","page":1879,"meaning_status":"draft","note":"ਜੰਗਿਰ: transliterated as printed; perhaps the Zangi (the people of Zang); uncertain.","meaning_pa":"ਜਦੋਂ ਉਸ ਨੇ ਰਾਜ-ਪਾਟ ਸੰਭਾਲਿਆ, ਤਾ ਪਹਿਲੀ ਲੜਾਈ ਜੰਗਿਰ ਨਾਲ ਕੀਤੀ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਤਾ ਕੋ ਦੇਸ ਛੀਨਿ ਕਰਿ ਲੀਨੋ। ਨਾਮੁ ਸਿਕੰਦਰ ਸਾਹ ਕੋ ਕੀਨੋ। ੨।","roman":"Taa ko des chheeni kari leeno | naamu sikandar saah ko keeno | 2 |","meaning_en":"He seized his country and made the name of Sikandar Shah renowned.","page":1879,"meaning_status":"draft","meaning_pa":"ਉਸ ਦਾ ਦੇਸ਼ ਖੋਹ ਲਿਆ ਅਤੇ ਆਪਣਾ ਨਾ ਸਿਕੰਦਰ ਸ਼ਾਹ ਰਖਿਆ ॥੨॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[3],"number_text":"੩।","page":1879,"lines":[{"gurmukhi":"ਬਹੁਰਿ ਸਾਹ ਦਾਰਾ ਕੌ ਮਾਰਿਯੋ। ਹਿੰਦੁਸਤਾ ਕੌ ਬਹੁਰਿ ਪਧਾਰਿਯੋ।","roman":"Bahuri saah daaraa kau maariyo | hindustaa kau bahuri padhaariyo |","meaning_en":"Then he killed Shah Dara, and then proceeded to Hindustan.","page":1879,"meaning_status":"draft","note":"ਦਾਰਾ: Darius.","meaning_pa":"ਫਿਰ ਉਸ ਨੇ ਦਾਰਾ ਬਾਦਸ਼ਾਹ ਨੂੰ ਮਾਰਿਆ ਅਤੇ ਮਗਰੋਂ ਹਿੰਦੁਸਤਾਨ ਵਲ ਚੜ੍ਰਹ ਆਇਆ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਕਨਕਬਜਾ ਏਸ੍ਵਰ ਕੌ ਜਿਨਿਯੋ। ਸਾਮੁਹਿ ਭਯੋ ਤਾਹਿ ਤਿਹ ਝਿਨਿਯੋ। ੩।","roman":"Kankabjaa esvar kau jiniyo | saamuhi bhayo taahi tih jhiniyo | 3 |","meaning_en":"He conquered the lord of Kanauj; whoever faced him, he struck down.","page":1879,"meaning_status":"draft","note":"ਕਨਕਬਜਾ ਏਸ੍ਵਰ: 'lord of Kanakabja' (Kanyakubja, Kanauj). ਝਿਨਿਯੋ: read as 'struck down/crushed'; uncertain.","meaning_pa":"(ਪਹਿਲਾ) ਕਾਨਕੁਬਜ ਦੇ ਰਾਜੇ (ਜਾ ਐਸ਼ਵਰਜ) ਨੂੰ ਜਿਤਿਆ (ਅਤੇ ਜੋ ਵੀ) ਸਾਹਮਣੇ ਆਇਆ, ਉਸ ਨੂੰ ਪਛਾੜ ਦਿੱਤਾ ॥੩॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1879,"meaning_status":"draft","meaning_pa":"ਦੋਹਰਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[4],"number_text":"੪।","page":1879,"lines":[{"gurmukhi":"ਪ੍ਰਥਮ ਸੁਤਾ ਰੂਮੀਨ ਕੀ ਕੀਯੋ ਬ੍ਯਾਹ ਬਨਾਇ।","roman":"Pratham sutaa roomeen kee keeyo byaah banaai |","meaning_en":"First he duly married the daughter of the Rumis,","page":1879,"meaning_status":"draft","note":"ਰੂਮੀਨ: the people of Rum.","meaning_pa":"ਪਹਿਲਾ ਰੂਮ ਦੇਸ (ਦੇ ਰਾਜੇ ਦੀ) ਲੜਕੀ ਨਾਲ ਵਿਆਹ ਕੀਤਾ","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਬਹੁਰਿ ਕਨੌਜਿਸ ਕੀ ਸੁਤਾ ਬਰੀ ਮ੍ਰਿਦੰਗ ਬਜਾਇ। ੪।","roman":"Bahuri kanaujis kee sutaa baree mridang bajaai | 4 |","meaning_en":"then he wed the daughter of the lord of Kanauj to the beat of the drum.","page":1879,"meaning_status":"draft","meaning_pa":"ਅਤੇ ਫਿਰ ਨਗਾਰਾ ਵਜਾ ਕੇ ਕਨੌਜ ਦੇ ਰਾਜੇ ਦੀ ਧੀ ਨੂੰ ਵਿਆਹਿਆ ॥੪॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":1879,"meaning_status":"draft","meaning_pa":"ਅੜਿਲ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[5],"number_text":"੫।","page":1879,"lines":[{"gurmukhi":"ਬਹੁਰਿ ਦੇਸ ਨੈਪਾਲ ਪਯਾਨੋ ਤਿਨ ਕਿਯੋ।","roman":"Bahuri des naipaal payaano tin kiyo |","meaning_en":"Then he set out for the land of Nepal","page":1879,"meaning_status":"draft","meaning_pa":"ਫਿਰ ਉਹ ਨਿਪਾਲ ਦੇਸ ਵਲ ਚਲਾ ਗਿਆ","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਕਸਤੂਰੀ ਕੇ ਮ੍ਰਿਗਨ ਬਹੁਤ ਬਿਧਿ ਗਹਿ ਲਿਯੋ।","roman":"Kastooree ke mrigan bahut bidhi gahi liyo |","meaning_en":"and captured musk deer in many ways.","page":1879,"meaning_status":"draft","meaning_pa":"ਅਤੇ ਬਹੁਤ ਢੰਗਾ ਨਾਲ ਕਸਤੂਰੀ ਵਾਲੇ ਹਿਰਨਾ ਨੂੰ ਪਕੜ ਲਿਆ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਬਹੁਰਿ ਬੰਗਾਲਾ ਕੀ ਦਿਸਿ ਆਪੁ ਪਧਾਰਿਯੋ।","roman":"Bahuri bangaalaa kee disi aapu padhaariyo |","meaning_en":"Then he himself proceeded towards Bengal;","page":1879,"meaning_status":"draft","meaning_pa":"ਫਿਰ ਆਪ ਬੰਗਾਲ ਵਲ ਚਲਾ ਗਿਆ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਹੋ ਆਨਿ ਮਿਲ੍ਯੋ ਸੋ ਬਚ੍ਯੋ ਅਰ੍ਯੋ ਤਿਹ ਮਾਰਿਯੋ। ੫।","roman":"Ho aani milyo so bachyo aryo tih maariyo | 5 |","meaning_en":"whoever came and submitted was spared, and whoever resisted he killed.","page":1879,"meaning_status":"draft","meaning_pa":"(ਉਸ ਨੂੰ) ਜੋ ਆ ਕੇ ਮਿਲ ਪਿਆ, ਉਹ ਬਚ ਗਿਆ ਅਤੇ ਜੋ ਅੜਿਆ, ਉਹ ਮਾਰ ਦਿੱਤਾ ॥੫॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[6],"number_text":"੬।","page":1881,"lines":[{"gurmukhi":"ਜੀਤ ਬੰਗਾਲਾ ਛਾਜ ਕਰਨ ਪਰ ਧਾਇਯੋ।","roman":"Jeet bangaalaa chhaaj karan par dhaaiyo |","meaning_en":"Having conquered Bengal he fell upon the Chhaj Karan;","page":1881,"meaning_status":"draft","note":"ਛਾਜ ਕਰਨ: 'those with ears like winnowing-baskets', a legendary people; uncertain.","meaning_pa":"ਬੰਗਾਲ ਨੂੰ ਜਿਤ ਕੇ ਫਿਰ 'ਛਾਜ ਕਰਨ' ਉਤੇ ਹਮਲਾ ਕੀਤਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਤਿਨੋ ਜੀਤਿ ਨਾਗਰ ਪਰ ਅਧਿਕ ਰਿਸਾਇਯੋ।","roman":"Tino jeeti naagar par adhik risaaiyo |","meaning_en":"conquering them, he grew very wrathful against the Nagar;","page":1881,"meaning_status":"draft","note":"ਨਾਗਰ: taken as the name of a people or place; uncertain.","meaning_pa":"ਉਨ੍ਰਹਾ ਨੂੰ ਜਿਤ ਕੇ ਫਿਰ ਨਾਗਰ (ਨਾਗ) ਦੇਸ਼ ਉਤੇ ਬਹੁਤ ਰੋਹ ਵਿਚ ਆਇਆ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਏਕਪਾਦ ਬਹੁ ਹਨੈ ਸੂਰ ਸਾਵਤ ਬਨੇ।","roman":"Ekpaad bahu hanai soor saavat bane |","meaning_en":"he killed many of the Ekpad, fine warriors and chieftains;","page":1881,"meaning_status":"draft","note":"ਏਕਪਾਦ: 'the one-footed', a legendary people.","meaning_pa":"(ਫਿਰ) ਏਕਪਾਦ (ਕੇਰਲ) ਪ੍ਰਦੇਸ ਵਿਚ ਬਹੁਤ ਸਾਰੇ ਸਾਮੰਤ ਅਤੇ ਸੂਰਮੇ ਮਾਰ ਦਿੱਤੇ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਹੋ ਜੀਤਿ ਪੂਰਬਹਿ ਕਿਯੋ ਪਯਾਨੋ ਦਛਿਨੇ। ੬।","roman":"Ho jeeti poorabhi kiyo payaano dachhine | 6 |","meaning_en":"having conquered the east he set out for the south.","page":1881,"meaning_status":"draft","meaning_pa":"(ਇਸ ਤਰ੍ਰਹਾ) ਪੂਰਬ ਨੂੰ ਜਿਤ ਕੇ ਦੱਖਣ ਵਲ ਚਲ ਪਿਆ ॥੬॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਛਪੈ ਛੰਦ","gurmukhi":"ਛਪੈ ਛੰਦ","roman":"Chhapai chhand","meaning_en":"Chhappai metre.","page":1881,"meaning_status":"draft","meaning_pa":"ਛਪੈ ਛੰਦ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[7],"number_text":"੭।","page":1881,"lines":[{"gurmukhi":"ਝਾਰਿ ਖੰਡਿਯਨ ਝਾਰਿ ਚਮਕਿ ਚਾਦਿਯਨ ਸੰਘਾਰਿਯੋ।","roman":"Jhaari khandiyan jhaari chamki chaadiyan sanghaariyo |","meaning_en":"He swept away the men of Jharkhand and in a flash destroyed the men of Chanda;","page":1881,"meaning_status":"draft","meaning_pa":"ਝਾੜ ਖੰਡ ਦੇ ਰਹਿਣ ਵਾਲਿਆਂ ਨੂੰ ਝਾੜਿਆ ਅਤੇ ਫਿਰ ਕ੍ਰੋਧਿਤ ਹੋ ਕੇ ਚਾਦ ਨਗਰ ਵਾਲਿਆਂ ਨੂੰ ਮਾਰ ਦਿੱਤਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਬਿਦ੍ਰਭ ਦੇਸਿਯਨ ਬਾਰਿ ਖੰਡ ਬੁੰਦੇਲ ਬਿਦਾਰਿਯੋ।","roman":"Bidrabh desiyan baari khand bundel bidaariyo |","meaning_en":"burning the men of the land of Vidarbh, he tore apart Bundelkhand;","page":1881,"meaning_status":"draft","note":"ਬਾਰਿ: read as 'burning'; uncertain.","meaning_pa":"(ਫਿਰ) ਬਿਦ੍ਰਭ ਦੇਸ਼ ਵਾਸੀਆਂ ਨੂੰ ਸਾੜ ਕੇ, ਬੁੰਦੇਲ ਖੰਡ (ਦੇ ਸੂਰਮਿਆਂ) ਨੂੰ ਨਸ਼ਟ ਕਰ ਦਿੱਤਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਖੜਗ ਪਾਨ ਗਹਿ ਖੇਤ ਖੁਨਿਸ ਖੰਡਿਸਨ ਬਿਹੰਡਿਯੋ।","roman":"Kharag paan gahi khet khunis khandisan bihandiyo |","meaning_en":"taking sword in hand, in fury on the field he shattered the lords of the regions;","page":1881,"meaning_status":"draft","note":"ਖੰਡਿਸਨ: read as 'lords of regions'; uncertain.","meaning_pa":"ਹੱਥ ਵਿਚ ਤਲਵਾਰ ਲੈ ਕੇ, ਯੁੱਧ-ਭੂਮੀ ਵਿਚ ਕ੍ਰੋਧਿਤ ਹੋ ਕੇ ਖੜਗਧਾਰੀਆਂ ਨੂੰ ਸੰਘਾਰ ਦਿੱਤਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਪੁਨਿ ਮਾਰਾਸਟ੍ਰ ਤਿਲੰਗ ਦ੍ਰੌੜ ਤਿਲ ਤਿਲ ਕਰਿ ਖੰਡਿਯੋ।","roman":"Puni maaraasatr tilang draur til til kari khandiyo |","meaning_en":"then he cut Maharashtra, Tilang and Dravid into tiny pieces.","page":1881,"meaning_status":"draft","meaning_pa":"ਫਿਰ ਮਹਾਰਾਸ਼ਟਰ, ਤਿਲੰਗ, ਦ੍ਰੜਾਵੜ (ਦੇਸ ਵਾਸੀਆਂ ਨੂੰ) ਤਿਲ ਤਿਲ ਕਰ ਕੇ ਕਟ ਸੁਟਿਆ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਨ੍ਰਿਪ ਸੂਰਬੀਰ ਸੁੰਦਰ ਸਰਸ ਮਹੀ ਦਈ ਮਹਿ ਇਸਨ ਗਹਿ।","roman":"Nrip soorbeer sundar saras mahee daee mahi isan gahi |","meaning_en":"The king, a brave warrior, handsome and fine, seized the lords of the earth and took the earth;","page":1881,"meaning_status":"draft","note":"ਮਹੀ ਦਈ ਮਹਿ ਇਸਨ ਗਹਿ: literally 'seizing the lords of the earth, the earth (was) given'; uncertain.","meaning_pa":"ਜਿਹੜੇ ਬਹੁਤ ਸੁੰਦਰ ਸ਼ੂਰਵੀਰ ਰਾਜੇ ਸਨ, (ਉਨ੍ਰਹਾ ਤੋਂ) ਧਰਤੀ ਲੈ ਕੇ ਫਿਰ ਵਾਪਸ ਕਰ ਦਿੱਤੀ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਦਛਨਹਿ ਜੀਤਿ ਪਟਨ ਉਪਟਿਸੁ ਕਿਯ ਪਯਾਨ ਪੁਨਿ ਪਸਚਮਹਿ। ੭।","roman":"Dachhanhi jeeti patan uptisu kiy payaan puni paschamhi | 7 |","meaning_en":"having conquered the south and uprooted its towns, he then set out for the west.","page":1881,"meaning_status":"draft","note":"ਪਟਨ ਉਪਟਿਸੁ: read as 'uprooted the towns'; uncertain.","meaning_pa":"ਦੱਖਣ ਦਿਸ਼ਾ ਨੂੰ ਜਿਤ ਕੇ ਅਤੇ 'ਪਟਨ' (ਨਗਰ) ਬਰਬਾਦ ਕਰ ਕੇ ਫਿਰ ਪੱਛਮ ਦਿਸ਼ਾ ਵਲ ਧਾਵਾ ਕੀਤਾ ॥੭॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":1881,"meaning_status":"draft","meaning_pa":"ਅੜਿਲ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[8],"number_text":"੮।","page":1881,"lines":[{"gurmukhi":"ਬਰਬਰੀਨ ਕੌ ਜੀਤਿ ਬਾਹੁ ਸਾਲੀਨ ਬਿਹੰਡਿਯੋ।","roman":"Barabreen kau jeeti baahu saaleen bihandiyo |","meaning_en":"Conquering the Barbaris, he shattered the mighty-armed;","page":1881,"meaning_status":"draft","note":"ਬਾਹੁ ਸਾਲੀਨ: 'those strong of arm'; may be the name of a people; uncertain.","meaning_pa":"ਬਰਬਰ ਦੇਸ਼ ਵਾਲਿਆਂ ਨੂੰ ਜਿਤ ਕੇ (ਫਿਰ) ਸ਼ਾਲੀਵਾਹਨ ਦੇਸ਼ ਵਾਲਿਆਂ ਦਾ ਵਿਨਾਸ਼ ਕੀਤਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਗਰਬ ਅਰਬ ਕੋ ਦਾਹਿ ਸਰਬ ਦਰਬਿਨ ਕੋ ਦੰਡਿਯੋ।","roman":"Garab arab ko daahi sarab darbin ko dandiyo |","meaning_en":"burning the pride of Arabia, he punished all the wealthy;","page":1881,"meaning_status":"draft","note":"ਦਰਬਿਨ: read as 'the wealthy'; may be the name of a people; uncertain.","meaning_pa":"(ਫਿਰ) ਅਰਬ ਦੇਸ਼ ਦੀ ਹੈਂਕੜ ਨੂੰ ਸਾੜ ਫੂਕ ਕੇ ਧਨਵਾਨਾ ('ਦਰਬਿਨ') ਨੂੰ ਦੰਡ ਦਿੱਤਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਅਰਬ ਖਰਬ ਰਿਪੁ ਚਰਬਿ ਜਰਬਿ ਛਿਨ ਇਕ ਮੈ ਮਾਰੇ।","roman":"Arab kharab ripu charbi jarbi chhin ik mai maare |","meaning_en":"arabs and kharabs of enemies he overpowered and struck down in a single instant;","page":1881,"meaning_status":"draft","note":"ਅਰਬ ਖਰਬ: very large numbers (thousands of millions). ਚਰਬਿ ਜਰਬਿ: 'overpowering, with blows'; uncertain.","meaning_pa":"ਫਿਰ ਬੇਗਿਣਤ ਵੈਰੀਆਂ ਨੂੰ ਚਬ ਲਿਆ ਅਤੇ ਦੁਖ ਦੇ ਕੇ ('ਜਰਬਿ' ਸੱਟਾ ਮਾਰ ਕੇ) ਛਿਣ ਵਿਚ ਮਾਰ ਦਿੱਤਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਹੋ ਹਿੰਗੁਲਾਜ ਹਬਸੀ ਹਰੇਵ ਹਲਬੀ ਹਨਿ ਡਾਰੇ। ੮।","roman":"Ho hingulaaj habsee harev halbee hani daare | 8 |","meaning_en":"he slew the men of Hinglaj, the Habshis, the men of Harev and of Halab.","page":1881,"meaning_status":"draft","note":"ਹਬਸੀ: Abyssinians; ਹਰੇਵ: Herat; ਹਲਬੀ: of Aleppo.","meaning_pa":"ਫਿਰ ਹਿੰਗਲਾਜ ਦੇਸ, ਹਬਸ਼ ਦੇਸ, ਹਰੇਵ ਦੇਸ ਅਤੇ ਹਲਬ ਦੇਸ਼ ਵਾਲਿਆਂ ਨੂੰ ਮਾਰ ਦਿੱਤਾ ॥੮॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[9],"number_text":"੯।","page":1881,"lines":[{"gurmukhi":"ਮਗਰਬੀਨ ਕੋ ਜੀਤਿ ਸਰਬ ਗਰਬਿਨ ਕੋ ਮਾਰਿਯੋ।","roman":"Magarbeen ko jeeti sarab garbin ko maariyo |","meaning_en":"Conquering the Maghribis, he killed all the proud;","page":1881,"meaning_status":"draft","note":"ਮਗਰਬੀਨ: 'westerners', men of the Maghrib.","meaning_pa":"ਫਿਰ ਪੱਛਮ ਨੂੰ ਜਿਤ ਕੇ ਸਾਰਿਆਂ ਹੰਕਾਰੀਆਂ ਨੂੰ ਮਾਰ ਦਿੱਤਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਸਰਬ ਚਰਬਿਯਨ ਚਰਬਿ ਗਰਬਿ ਗਜਨੀ ਕੋ ਗਾਰਿਯੋ।","roman":"Sarab charbiyan charbi garbi gajnee ko gaariyo |","meaning_en":"overpowering all the overbearing, he crushed the pride of Ghazni;","page":1881,"meaning_status":"draft","note":"ਚਰਬਿਯਨ ਚਰਬਿ: read as 'overpowering the overbearing'; uncertain.","meaning_pa":"ਸਾਰੇ ਸ਼ਕਤੀਵਰਾ ਨੂੰ ਚਬਿਆ ਅਤੇ ਗ਼ਜ਼ਨੀ ਦੇ ਗਰਬ ਨੂੰ ਨਸ਼ਟ ਕੀਤਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਮਾਲਨੇਰ ਮੁਲਤਾਨ ਮਾਲਵਾ ਬਸਿ ਕਿਯੋ।","roman":"Maalner multaan maalvaa basi kiyo |","meaning_en":"he brought Malner, Multan and Malwa under his sway,","page":1881,"meaning_status":"draft","meaning_pa":"(ਫਿਰ) ਮਾਲਨੇਰ, ਮੁਲਤਾਨ ਅਤੇ ਮਾਲਵਾ ਦੇਸ਼ ਨੂੰ ਵਸ ਵਿਚ ਕੀਤਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਹੋ ਦੁੰਦਭਿ ਜੀਤ ਪ੍ਰਤੀਚੀ ਦਿਸਿ ਜੈ ਕੋ ਦਿਯੋ। ੯।","roman":"Ho dundbhi jeet prateechee disi jai ko diyo | 9 |","meaning_en":"and sounded the drum of victory in the western quarter.","page":1881,"meaning_status":"draft","meaning_pa":"(ਇਸ ਤਰ੍ਰਹਾ) ਪੱਛਮ ਦਿਸ਼ਾ ਨੂੰ ਜਿਤ ਕੇ 'ਜੈ' ਦਾ ਨਗਾਰਾ ਵਜਾਇਆ ॥੯॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1881,"meaning_status":"draft","meaning_pa":"ਦੋਹਰਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[10],"number_text":"੧੦।","page":1881,"lines":[{"gurmukhi":"ਤੀਨਿ ਦਿਸਾ ਕੋ ਜੀਤਿ ਕੈ ਉਤਰ ਕਿਯੋ ਪਯਾਨ।","roman":"Teeni disaa ko jeeti kai utar kiyo payaan |","meaning_en":"Having conquered three quarters he set out for the north,","page":1881,"meaning_status":"draft","meaning_pa":"ਤਿੰਨ ਦਿਸ਼ਾਵਾ ਨੂੰ ਜਿਤ ਕੇ ਉੱਤਰ ਦਿਸ਼ਾ ਵਲ ਪ੍ਰਸਥਾਨ ਕੀਤਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਸਭ ਦੇਸੀ ਰਾਜਾਨ ਲੈ ਦੈ ਕੈ ਜੀਤ ਨਿਸਾਨ। ੧੦।","roman":"Sabh desee raajaan lai dai kai jeet nisaan | 10 |","meaning_en":"taking with him all the kings of the lands, and sounding the drum of victory.","page":1881,"meaning_status":"draft","note":"ਨਿਸਾਨ: 'drum' or 'standard'.","meaning_pa":"ਸਭ ਦੇਸਾ ਦੇ ਰਾਜਿਆਂ ਨੂੰ ਜਿਤ ਦੇ ਧੌਂਸੇ ਪ੍ਰਦਾਨ ਕਰ ਕੇ ਨਾਲ ਲੈ ਲਿਆ ॥੧੦॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[11],"number_text":"੧੧।","page":1881,"lines":[{"gurmukhi":"ਦੇਸ ਦੇਸ ਕੇ ਏਸ ਸਭ ਅਪਨੀ ਅਪਨੀ ਸੈਨ।","roman":"Des des ke es sabh apnee apnee sain |","meaning_en":"The lords of every land, each with his own army,","page":1881,"meaning_status":"draft","meaning_pa":"ਦੇਸ਼ਾ ਦੇਸ਼ਾ ਦੇ ਸਾਰੇ ਸੂਰਬੀਰ ਅਤੇ ਸੁੰਦਰਤਾ ਦੇ ਪੁੰਜ ਰਾਜੇ","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜੋਰਿ ਸਿਕੰਦਰਿ ਸੇ ਚੜੇ ਸੂਰ ਸਰਸ ਸਭ ਐਨ। ੧੧।","roman":"Jori sikandri se chare soor saras sabh ain | 11 |","meaning_en":"gathered and marched with Sikandar, fine warriors all.","page":1881,"meaning_status":"draft","note":"ਸਭ ਐਨ: read as 'all, indeed'; uncertain.","meaning_pa":"ਆਪਣੀ ਆਪਣੀ ਸੈਨਾ ਇਕੱਠੀ ਕਰ ਕੇ ਸਿਕੰਦਰ ਦੇ ਨਾਲ ਚੜ੍ਰਹ ਪਏ ॥੧੧॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਭੁਜੰਗ ਛੰਦ","gurmukhi":"ਭੁਜੰਗ ਛੰਦ","roman":"Bhujang chhand","meaning_en":"Bhujang metre.","page":1881,"meaning_status":"draft","meaning_pa":"ਭੁਜੰਗ ਛੰਦ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[12],"number_text":"੧੨।","page":1881,"lines":[{"gurmukhi":"ਚੜੇ ਉਤਰਾ ਪੰਥ ਕੇ ਬੀਰ ਭਾਰੇ। ਬਜੇ ਘੋਰ ਬਾਦਿਤ੍ਰ ਭੇਰੀ ਨਗਾਰੇ।","roman":"Chare utraa panth ke beer bhaare | baje ghor baaditr bheree nagaare |","meaning_en":"The great heroes marched upon the northern road; dreadful instruments, kettledrums and drums sounded.","page":1881,"meaning_status":"draft","meaning_pa":"ਉਤਰ ਦਿਸ਼ਾ ਦੇ ਸਾਰੇ ਮਹਾਨ ਸੂਰਮੇ ਚੜ੍ਰਹ ਪਏ ਅਤੇ ਭਾਰੀ ਜੰਗੀ ਵਾਜੇ ਵਜਣ ਲਗ ਪਏ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਪ੍ਰਿਥੀ ਚਾਲ ਕੀਨੋ ਦਸੋ ਨਾਗ ਭਾਗੇ। ਭਯੋ ਸੋਰ ਭਾਰੋ ਮਹਾ ਰੁਦ੍ਰ ਜਾਗੇ। ੧੨।","roman":"Prithee chaal keeno daso naag bhaage | bhayo sor bhaaro mahaa rudr jaage | 12 |","meaning_en":"The earth shook and the ten Nagas fled; there was a mighty din and the great Rudra awoke.","page":1881,"meaning_status":"draft","note":"ਦਸੋ ਨਾਗ: 'the ten Nagas (serpents)', or the elephants of the ten directions; uncertain.","meaning_pa":"ਪ੍ਰਿਥਵੀ ਡੋਲਣ ਲਗ ਗਈ ਅਤੇ ਦਸਾ ਦਿਸ਼ਾਵਾ ਦੇ ਹਾਥੀ ('ਨਾਗ') ਭਜ ਗਏ। ਬਹੁਤ ਅਧਿਕ ਸ਼ੋਰ ਹੋਇਆ (ਜਿਸ ਕਰ ਕੇ) ਮਹਾ ਰੁਦ੍ਰ ਦੀ ਸਮਾਧੀ ਖੁਲ੍ਰਹ ਗਈ ॥੧੨॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1881,"meaning_status":"draft","meaning_pa":"ਚੌਪਈ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[13],"number_text":"੧੩।","page":1881,"lines":[{"gurmukhi":"ਪ੍ਰਥਮਹਿ ਜਾਇ ਬਲਖ ਕੌ ਮਾਰਿਯੋ। ਸਹਿਰ ਬੁਖਾਰਾ ਬਹੁਰਿ ਉਜਾਰਿਯੋ।","roman":"Prathamhi jaai balakh kau maariyo | sahir bukhaaraa bahuri ujaariyo |","meaning_en":"First he went and struck Balkh, then he laid waste the city of Bukhara.","page":1881,"meaning_status":"draft","meaning_pa":"ਪਹਿਲਾ ਬਲਖ ਦੇਸ਼ ਨੂੰ ਜਾ ਕੇ ਮਾਰਿਆ। ਫਿਰ ਬੁਖਾਰਾ ਸ਼ਹਿਰ ਨੂੰ ਉਜਾੜਿਆ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਤਿਬਿਤ ਜਾਇ ਤਲਬ ਕੌ ਦੀਨੋ। ਜੀਤਿ ਦੇਸ ਅਪਨੇ ਬਸਿ ਕੀਨੋ। ੧੩।","roman":"Tibit jaai talab kau deeno | jeeti des apne basi keeno | 13 |","meaning_en":"Going to Tibet he made his demand, and conquering the country brought it under his sway.","page":1881,"meaning_status":"draft","note":"ਤਲਬ ਕੌ ਦੀਨੋ: 'gave a summons/demand'; uncertain.","meaning_pa":"ਤਿਬਤ ਦੇਸ਼ ਵਿਚ ਪਹੁੰਚ ਕੇ ਸਦਾ ਦਿੱਤਾ (ਭਾਵ ਵੰਗਾਰਿਆ) ਅਤੇ ਉਸ ਦੇਸ਼ ਨੂੰ ਜਿਤ ਕੇ ਆਪਣੇ ਅਧੀਨ ਕਰ ਲਿਆ ॥੧੩॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":1883,"meaning_status":"draft","meaning_pa":"ਅੜਿਲ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[14],"number_text":"੧੪।","page":1883,"lines":[{"gurmukhi":"ਕਾਸਮੀਰ ਕਸਿਕਾਰ ਕਬੁਜ ਕਾਬਲ ਕੌ ਕੀਨੋ।","roman":"Kaasmeer kasikaar kabuj kaabal kau keeno |","meaning_en":"He took possession of Kashmir, Kashgar and Kabul;","page":1883,"meaning_status":"draft","note":"ਕਸਿਕਾਰ: Kashgar. ਕਬੁਜ: read as Persian qabz, 'possession'; it could be a place-name (Kamboj); uncertain.","meaning_pa":"ਕਸ਼ਮੀਰ, ਕਾਸ਼ਗਾਰ, ਕੰਬੋਜ, ਕਾਬਲ,","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਕਸਟਵਾਰ ਕੁਲੂ ਕਲੂਰ ਕੈਠਲ ਕਹ ਲੀਨੋ।","roman":"Kasatvaar kuloo kaloor kaithal kah leeno |","meaning_en":"he took Kashtwar, Kulu, Kahlur and Kaithal;","page":1883,"meaning_status":"draft","meaning_pa":"ਕਸਟਵਾਰ, ਕੁਲੂ, ਕਲੂਰ, ਕੈਠਲ (ਕੈਥਲ) ਆਦਿ ਨੂੰ ਪ੍ਰਾਪਤ ਕੀਤਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਕਾਂਬੋਜ ਕਿਲਮਾਕ ਕਠਿਨ ਪਲ ਮੈ ਕਟਿ ਡਾਰੇ।","roman":"Kaanboj kilmaak kathin pal mai kati daare |","meaning_en":"the hard Kambojas and Kilmaks he cut down in a moment;","page":1883,"meaning_status":"draft","note":"ਕਿਲਮਾਕ: the Kalmyks."},{"gurmukhi":"ਹੋ ਕੋਟਿ ਚੀਨ ਕੇ ਕਟਕ ਹਨੇ ਕਰਿ ਕੋਪ ਕਰਾਰੇ। ੧੪।","roman":"Ho koti cheen ke katak hane kari kop karaare | 14 |","meaning_en":"in fierce anger he slew crores of the armies of China.","page":1883,"meaning_status":"draft","meaning_pa":"ਕੰਬੋਜ, ਕਿਲਮਾਕ ਆਦਿ ਕਠੋਰ (ਸੂਰਮਿਆਂ) ਨੂੰ ਪਲਾ ਵਿਚ ਕਟ ਸੁਟਿਆ ਅਤੇ ਬਹੁਤ ਕ੍ਰੋਧ ਵਿਚ ਆ ਕੇ ਚੀਨ ਦੀ ਬੇਸ਼ੁਮਾਰ ਫ਼ੌਜ ਮਾਰ ਦਿੱਤੀ ॥੧੪॥","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1883,"meaning_status":"draft","meaning_pa":"ਦੋਹਰਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[15],"number_text":"੧੫।","page":1883,"lines":[{"gurmukhi":"ਬਹੁਰਿ ਚੀਨ ਮਾਚੀਨ ਕੀ ਦਿਸਿ ਕੌ ਕਿਯੋ ਪਯਾਨ।","roman":"Bahuri cheen maacheen kee disi kau kiyo payaan |","meaning_en":"Then he set out towards China and Machin;","page":1883,"meaning_status":"draft","meaning_pa":"ਫਿਰ ਚੀਨ ਮਾਚੀਨ ਦੀ ਦਿਸ਼ਾ ਵਲ ਪ੍ਰਸਥਾਨ ਕੀਤਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਲੈ ਲੌਡੀ ਰਾਜਾ ਮਿਲਿਯੋ ਸਾਹ ਸਿਕੰਦਰਹਿ ਆਨਿ। ੧੫।","roman":"Lai laudee raajaa miliyo saah sikandarhi aani | 15 |","meaning_en":"the king came and met Shah Sikandar, bringing a slave-girl.","page":1883,"meaning_status":"draft","meaning_pa":"ਅਗੋਂ (ਉਥੋਂ ਦਾ) ਰਾਜਾ ਸਿਕੰਦਰ ਸ਼ਾਹ ਨੂੰ ਲੌਂਡੀ (ਲੜਕੀ) ਲੈ ਕੇ ਆ ਮਿਲਿਆ ॥੧੫॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[16],"number_text":"੧੬।","page":1883,"lines":[{"gurmukhi":"ਜੀਤਿ ਚੀਨ ਮਾਚੀਨ ਕੌ ਬਸਿ ਕੀਨੀ ਦਿਸਿ ਚਾਰਿ।","roman":"Jeeti cheen maacheen kau basi keenee disi chaari |","meaning_en":"Having conquered China and Machin he had brought the four quarters under his sway;","page":1883,"meaning_status":"draft","meaning_pa":"ਚੀਨ ਮਾਚੀਨ ਨੂੰ ਜਿਤ ਕੇ ਚਾਰੇ ਦਿਸ਼ਾਵਾ ਵਸ ਵਿਚ ਕਰ ਲਈਆਂ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਬਹੁਰਿ ਸਮੁੰਦ ਮਾਪਨ ਨਿਮਿਤ ਮਨ ਮੈ ਕੀਯੋ ਬੀਚਾਰਿ। ੧੬।","roman":"Bahuri samund maapan nimit man mai keeyo beechaari | 16 |","meaning_en":"then he formed in his mind the thought of measuring the ocean.","page":1883,"meaning_status":"draft","meaning_pa":"ਫਿਰ ਸਮੁੰਦਰ ਨੂੰ ਮਾਪਣ ਲਈ (ਭਾਵ ਜਿਤਣ ਲਈ) ਮਨ ਵਿਚ ਵਿਚਾਰ ਕੀਤਾ ॥੧੬॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":1883,"meaning_status":"draft","meaning_pa":"ਅੜਿਲ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[17],"number_text":"੧੭।","page":1883,"lines":[{"gurmukhi":"ਵੁਲੰਦੇਜਿਯਨ ਜੀਤਿ ਅੰਗਰੇਜਿਯਨ ਕੌ ਮਾਰਿਯੋ।","roman":"Vulandejiyan jeeti angrejiyan kau maariyo |","meaning_en":"Conquering the Hollanders, he struck the English;","page":1883,"meaning_status":"draft","note":"ਵੁਲੰਦੇਜਿਯਨ: the Dutch; ਅੰਗਰੇਜਿਯਨ: the English.","meaning_pa":"ਵਲੰਦੇਜੀਆਂ ਨੂੰ ਜਿਤ ਕੇ ਅੰਗ੍ਰੇਜ਼ਾ ਨੂੰ ਮਾਰਿਆ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਮਛਲੀ ਬੰਦਰ ਮਾਰਿ ਬਹੁਰਿ ਹੁਗਲਿਯਹਿ ਉਜਾਰਿਯੋ।","roman":"Machhlee bandar maari bahuri hugliyhi ujaariyo |","meaning_en":"striking Machhli Bandar, he then laid waste Hugli;","page":1883,"meaning_status":"draft","note":"ਮਛਲੀ ਬੰਦਰ: the port of Machilipatnam.","meaning_pa":"ਮੱਛਲੀ ਬੰਦਰ ਨੂੰ ਜਿਤ ਕੇ ਫਿਰ ਹੁਗਲੀ ਬੰਦਰ ਨੂੰ ਉਜਾੜਿਆ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਕੋਕ ਬੰਦਰ ਕੌ ਜੀਤਿ ਗੂਆ ਬੰਦਰ ਹੂੰ ਲੀਨੋ।","roman":"Kok bandar kau jeeti gooaa bandar hoon leeno |","meaning_en":"conquering Kok Bandar, he took the port of Goa too;","page":1883,"meaning_status":"draft","meaning_pa":"ਕੋਕ ਬੰਦਰ ਨੂੰ ਜਿਤ ਕੇ ਫਿਰ ਗੁਆ ਬੰਦਰ ਨੂੰ ਅਧੀਨ ਕੀਤਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਹੋ ਹਿਜਲੀ ਬੰਦਰ ਜਾਇ ਬਿਜੈ ਦੁੰਦਭਿ ਕਹ ਦੀਨੋ। ੧੭।","roman":"Ho hijlee bandar jaai bijai dundbhi kah deeno | 17 |","meaning_en":"going to the port of Hijli he sounded the drum of victory.","page":1883,"meaning_status":"draft","meaning_pa":"(ਫਿਰ) ਹਿਜਲੀ ਬੰਦਰ ਵਿਚ ਜਾ ਕੇ ਜਿਤ ਦਾ ਧੌਂਸਾ ਵਜਾਇਆ ॥੧੭॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[18],"number_text":"੧੮।","page":1883,"lines":[{"gurmukhi":"ਸਾਤ ਸਮੁੰਦ੍ਰਨ ਮਾਪਿ ਪ੍ਰਿਥੀ ਤਲ ਕੌ ਗਯੋ।","roman":"Saat samundran maapi prithee tal kau gayo |","meaning_en":"Having measured the seven seas he went down below the earth;","page":1883,"meaning_status":"draft","note":"ਪ੍ਰਿਥੀ ਤਲ ਕੌ ਗਯੋ: read as 'went beneath the earth' in view of the next line; literally 'went to the earth's surface/bottom'.","meaning_pa":"ਸੱਤ ਸਮੁੰਦਰਾ ਨੂੰ ਪਾਰ ਕਰ ਕੇ ਫਿਰ ਪਾਤਾਲ ਲੋਕ ('ਪ੍ਰਿਥੀ ਤਲ') ਵਿਚ ਗਿਆ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜੀਤਿ ਰਸਾਤਲ ਸਾਤ ਸ੍ਵਰਗ ਕੋ ਮਗ ਲਿਯੋ।","roman":"Jeeti rasaatal saat svarag ko mag liyo |","meaning_en":"conquering the seven nether worlds he took the road to heaven;","page":1883,"meaning_status":"draft","meaning_pa":"ਸੱਤ ਪਾਤਾਲਾ ਨੂੰ ਜਿਤ ਕੇ ਸਵਰਗ ਦਾ ਰਾਹ ਪਕੜਿਆ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਇੰਦ੍ਰ ਸਾਥ ਹੂੰ ਲਰਿਯੋ ਅਧਿਕ ਰਿਸਿ ਠਾਨਿ ਕੈ।","roman":"Indr saath hoon lariyo adhik risi thaani kai |","meaning_en":"he fought even with Indra in great wrath,","page":1883,"meaning_status":"draft","meaning_pa":"ਇੰਦਰ ਨਾਲ ਬਹੁਤ ਕ੍ਰੋਧ ਕਰ ਕੇ ਲੜਿਆ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਹੋ ਬਹੁਰਿ ਪ੍ਰਿਥੀ ਤਲ ਮਾਝ ਪ੍ਰਗਟਿਯੋ ਆਨਿ ਕੈ। ੧੮।","roman":"Ho bahuri prithee tal maajh pragtiyo aani kai | 18 |","meaning_en":"and then came and appeared again upon the face of the earth.","page":1883,"meaning_status":"draft","meaning_pa":"ਫਿਰ ਪ੍ਰਿਥਵੀ ਤਲ ਵਿਚ ਆ ਪ੍ਰਗਟ ਹੋਇਆ ॥੧੮॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1883,"meaning_status":"draft","meaning_pa":"ਦੋਹਰਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[19],"number_text":"੧੯।","page":1883,"lines":[{"gurmukhi":"ਲੋਕ ਚੌਦਹੁੰ ਬਸਿ ਕੀਏ ਜੀਤਿ ਪ੍ਰਿਥੀ ਸਭ ਲੀਨ।","roman":"Lok chaudhun basi kee'e jeeti prithee sabh leen |","meaning_en":"He brought the fourteen worlds under his sway and conquered the whole earth;","page":1883,"meaning_status":"draft"},{"gurmukhi":"ਬਹੁਰਿ ਰੂਸ ਕੇ ਦੇਸ ਕੀ ਓਰ ਪਯਾਨੋ ਕੀਨ। ੧੯।","roman":"Bahuri roos ke des kee or payaano keen | 19 |","meaning_en":"then he set out towards the land of Rus.","page":1883,"meaning_status":"draft","note":"ਰੂਸ: Russia.","meaning_pa":"ਸਾਰੀ ਪ੍ਰਿਥਵੀ ਨੂੰ ਜਿਤ ਕੇ ਚੌਦਾ ਲੋਕਾ ਨੂੰ ਵਸ ਵਿਚ ਕੀਤਾ। ਫਿਰ ਰੂਸ ਦੇਸ ਵਲ ਪ੍ਰਸਥਾਨ ਕੀਤਾ ॥੧੯॥","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1883,"meaning_status":"draft","meaning_pa":"ਚੌਪਈ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[20],"number_text":"੨੦।","page":1883,"lines":[{"gurmukhi":"ਬੀਰਜ ਸੈਨ ਰੂਸ ਕੋ ਰਾਜਾ। ਜਾ ਤੇ ਮਹਾ ਰੁਦ੍ਰ ਸੋ ਭਾਜਾ।","roman":"Beeraj sain roos ko raajaa | jaa te mahaa rudr so bhaajaa |","meaning_en":"Biraj Sain was the king of Rus, from whom even the great Rudra had fled.","page":1883,"meaning_status":"draft","meaning_pa":"ਬੀਰਜ ਸੈਨ ਰੂਸ ਦਾ ਰਾਜਾ ਸੀ ਜਿਸ ਤੋਂ ਮਹਾ ਰੁਦ੍ਰ ਵਰਗਾ ਵੀ ਭਜ ਗਿਆ ਸੀ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜਬ ਤਿਨ ਸੁਨ੍ਯੋ ਸਿਕੰਦਰ ਆਯੋ। ਆਨਿ ਅਗਮਨੈ ਜੁਧ ਮਚਾਯੋ। ੨੦।","roman":"Jab tin sunyo sikandar aayo | aani agamnai judh machaayo | 20 |","meaning_en":"When he heard that Sikandar had come, he came forward and raised battle.","page":1883,"meaning_status":"draft","meaning_pa":"ਜਦ ਉਸ ਨੇ ਸੁਣਿਆ ਕਿ ਸਿਕੰਦਰ ਆਇਆ ਹੈ ਤਾ ਉਸ ਨੇ ਅਗੇ ਵੱਧ ਕੇ ਯੁੱਧ ਮਚਾ ਦਿੱਤਾ ॥੨੦॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[21],"number_text":"੨੧।","page":1883,"lines":[{"gurmukhi":"ਤਹਾ ਯੁਧ ਗਾੜੋ ਅਤਿ ਮਾਚਿਯੋ। ਬਿਨੁ ਬ੍ਰਿਣ ਏਕ ਸੁਭਟ ਨਹਿ ਬਾਚਿਯੋ।","roman":"Tahaa yudh gaaro ati maachiyo | binu brin ek subhat nahi baachiyo |","meaning_en":"A very fierce battle raged there; not one warrior escaped without a wound.","page":1883,"meaning_status":"draft","meaning_pa":"ਉਥੇ ਬਹੁਤ ਘਮਸਾਨ ਯੁੱਧ ਹੋਇਆ ਅਤੇ ਬਿਨਾ ਜ਼ਖ਼ਮ ਲਗੇ ਇਕ ਸੂਰਮਾ ਵੀ ਨਾ ਬਚਿਆ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਹਾਰਿ ਪਰੇ ਇਕ ਜਤਨ ਬਨਾਯੋ। ਦੈਤ ਹੁਤੋ ਇਕ ਤਾਹਿ ਬੁਲਾਯੋ। ੨੧।","roman":"Haari pare ik jatan banaayo | dait huto ik taahi bulaayo | 21 |","meaning_en":"When they were losing they devised a plan: there was a demon, and they called him.","page":1883,"meaning_status":"draft","note":"'They' are taken as the men of Rus, for whom the demon then fights.","meaning_pa":"(ਜਦੋਂ ਉਹ ਸਾਰੇ) ਹਾਰਨ ਲਗੇ ਤਾ ਇਕ ਯਤਨ ਕੀਤਾ। (ਉਥੇ) ਇਕ ਦੈਂਤ ਹੁੰਦਾ ਸੀ, ਉਸ ਨੂੰ ਬੁਲਾਇਆ ॥੨੧॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1883,"meaning_status":"draft","meaning_pa":"ਦੋਹਰਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[22],"number_text":"੨੨।","page":1883,"lines":[{"gurmukhi":"ਕੁਹਨ ਪੋਸਤੀ ਤਨ ਧਰੇ ਆਵਤ ਭਯੋ ਬਜੰਗ।","roman":"Kuhan postee tan dhare aavat bhayo bajang |","meaning_en":"Wearing an old hide on his body, he came to battle,","page":1883,"meaning_status":"draft","note":"ਕੁਹਨ ਪੋਸਤੀ: Persian, 'old skin/fur garment'. ਬਜੰਗ: Persian ba-jang, 'to battle'; uncertain.","meaning_pa":"ਪੁਰਾਣੀ ('ਕੁਹਨ') ਪੋਸਤੀਨ ਸ਼ਰੀਰ ਉਤੇ ਧਾਰਨ ਕੀਤੇ ਹੋਇਆਂ (ਉਹ ਦੈਂਤ) ਜੰਗ ਕਰਨ ਲਈ ਆ ਗਿਆ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜਨੁਕ ਲਹਿਰ ਦਰਿਯਾਵ ਤੇ ਨਿਕਸਿਯੋ ਬਡੋ ਨਿਹੰਗ। ੨੨।","roman":"Januk lahir dariyaav te niksiyo bado nihang | 22 |","meaning_en":"as if a great crocodile had come out of the waves of the river.","page":1883,"meaning_status":"draft","note":"ਨਿਹੰਗ: crocodile.","meaning_pa":"(ਇੰਜ ਪ੍ਰਤੀਤ ਹੁੰਦਾ ਸੀ) ਮਾਨੋ ਦਰਿਆ ਦੀ ਲਹਿਰ ਤੋਂ ਕੋਈ ਵੱਡਾ ਮਗਰਮਛ ਨਿਕਲਿਆ ਹੋਵੇ ॥੨੨॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1885,"meaning_status":"draft","meaning_pa":"ਚੌਪਈ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[23],"number_text":"੨੩।","page":1885,"lines":[{"gurmukhi":"ਜੋ ਕਬਹੂੰ ਕਰ ਕੋ ਬਲ ਕਰੈ। ਹਾਥ ਭਏ ਹੀਰਾ ਮਲਿ ਡਰੈ।","roman":"Jo kabhoon kar ko bal karai | haath bhae heeraa mali darai |","meaning_en":"If ever he exerted the strength of his hand, he would crush a diamond in his hand;","page":1885,"meaning_status":"draft","meaning_pa":"ਜੇ ਉਹ ਕਦੇ ਹੱਥ ਦਾ ਜ਼ੋਰ ਲਗਾਦਾ ਤਾ ਹੱਥਾ ਨਾਲ ਹੀਰਾ ਮਸਲ ਦਿੰਦਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜਹਾ ਕੂਦਿ ਕਰਿ ਕੋਪ ਦਿਖਾਵੈ। ਤੌਨੈ ਠੌਰ ਕੂਪ ਪਰਿ ਜਾਵੈ। ੨੩।","roman":"Jahaa koodi kari kop dikhaavai | taunai thaur koop pari jaavai | 23 |","meaning_en":"wherever he leapt and showed his anger, a well would form in that place.","page":1885,"meaning_status":"draft","meaning_pa":"ਜਿਥੇ ਕੁਦ ਕੇ ਕ੍ਰੋਧ ਪ੍ਰਗਟ ਕਰਦਾ, ਉਥੇ ਡੂੰਘਾ ਟੋਆ ਪੈ ਜਾਦਾ ॥੨੩॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1885,"meaning_status":"draft","meaning_pa":"ਦੋਹਰਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[24],"number_text":"੨੪।","page":1885,"lines":[{"gurmukhi":"ਏਕ ਗਦਾ ਕਰ ਮੈ ਧਰੈ ਔਰਨ ਫਾਸੀ ਪ੍ਰਾਸ।","roman":"Ek gadaa kar mai dharai auran phaasee praas |","meaning_en":"In one hand he held a mace, in the others a noose and a spear;","page":1885,"meaning_status":"draft","meaning_pa":"(ਉਸ ਨੇ) ਇਕ ਹੱਥ ਵਿਚ ਗਦਾ ਧਾਰਨ ਕੀਤਾ ਹੋਇਆ ਸੀ ਅਤੇ ਹੋਰਨਾ ਵਿਚ ਫਾਹੀ ਅਤੇ ਕੁਹਾੜਾ (ਪਕੜਿਆ ਹੋਇਆ ਸੀ)।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਪਾਚ ਸਹਸ੍ਰ ਸ੍ਵਾਰ ਤੇ ਮਾਰਤ ਤਾ ਕੌ ਤ੍ਰਾਸੁ। ੨੪।","roman":"Paach sahasr svaar te maarat taa kau traasu | 24 |","meaning_en":"the dread of him struck down five thousand horsemen.","page":1885,"meaning_status":"draft","note":"ਪਾਚ ਸਹਸ੍ਰ ਸ੍ਵਾਰ ਤੇ ਮਾਰਤ ਤਾ ਕੌ ਤ੍ਰਾਸੁ: sense uncertain; perhaps 'his terror was more deadly than five thousand horsemen'.","meaning_pa":"ਉਸ ਦਾ (ਕੇਵਲ) ਡਰ ਹੀ ਪੰਜ ਹਜ਼ਾਰ ਸਿਪਾਹੀਆਂ ਨੂੰ ਮਾਰ ਦਿੰਦਾ ਸੀ ॥੨੪॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1885,"meaning_status":"draft","meaning_pa":"ਚੌਪਈ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[25],"number_text":"੨੫।","page":1885,"lines":[{"gurmukhi":"ਜਾ ਕੌ ਐਚ ਗਦਾ ਕੀ ਮਾਰੈ। ਤਾ ਕੋ ਮੂੰਡ ਫੋਰ ਹੀ ਡਾਰੈ।","roman":"Jaa kau aich gadaa kee maarai | taa ko moond phor hee daarai |","meaning_en":"Whomever he struck with a swing of the mace, he smashed his head outright.","page":1885,"meaning_status":"draft","meaning_pa":"ਜਿਸ ਨੂੰ ਖਿਚ ਕੇ ਗਦਾ ਮਾਰਦਾ ਸੀ, ਉਸ ਦਾ ਸਿਰ ਫੋੜ ਦਿੰਦਾ ਸੀ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਰਿਸ ਭਰਿ ਪਵਨ ਬੇਗਿ ਜ੍ਯੋ ਧਾਵੈ। ਪਤ੍ਰਨ ਜ੍ਯੋ ਛਤ੍ਰਿਯਨ ਭਜਾਵੇ। ੨੫।","roman":"Ris bhari pavan begi jyo dhaavai | patran jyo chhatriyan bhajaave | 25 |","meaning_en":"Filled with rage he rushed with the speed of the wind and drove the Kshatriyas off like leaves.","page":1885,"meaning_status":"draft","meaning_pa":"ਜਦੋਂ ਕ੍ਰੋਧ ਨਾਲ ਭਰ ਕੇ ਹਵਾ ਵਾਗ ਚਲਦਾ ਸੀ, ਤਾ ਪੱਤਰਾ ਵਾਗ ਛਤ੍ਰੀਆਂ ਨੂੰ ਭਜਾ ਦਿੰਦਾ ਸੀ (ਭਾਵ ਉਡਾ ਲੈ ਜਾਦਾ ਸੀ) ॥੨੫॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[26],"number_text":"੨੬।","page":1885,"lines":[{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਤਿਨ ਬੀਰ ਖਪਾਏ। ਮੋ ਪਹਿ ਤੇ ਨਹਿ ਜਾਤ ਗਨਾਏ।","roman":"Bhaati bhaati tin beer khapaae | mo pahi te nahi jaat ganaae |","meaning_en":"In many ways he destroyed warriors; they cannot be counted by me.","page":1885,"meaning_status":"draft","meaning_pa":"ਉਸ ਨੇ ਭਾਤ ਭਾਤ ਦੇ ਸੂਰਮੇ ਖਪਾ ਦਿੱਤੇ ਸਨ, ਜਿਨ੍ਰਹਾ ਦੀ ਗਿਣਤੀ ਮੇਰੇ ਪਾਸੋਂ ਨਹੀਂ ਕੀਤੀ ਜਾ ਸਕਦੀ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜੌ ਤਿਨ ਕੇ ਨਾਮਨ ਹ੍ਯਾ ਧਰਿਯੈ। ਏਕ ਗ੍ਰੰਥ ਇਨਹੀ ਕੋ ਭਰਿਯੈ। ੨੬।","roman":"Jau tin ke naaman hyaa dhariyai | ek granth inhee ko bhariyai | 26 |","meaning_en":"If their names were set down here, a whole book would be filled with them alone.","page":1885,"meaning_status":"draft","meaning_pa":"ਜੇ ਉਨ੍ਰਹਾ ਦੇ ਨਾਵਾ ਨੂੰ ਇਥੇ ਲਿਖਾ ਤਾ ਇਕ ਗ੍ਰੰਥ ਇਨ੍ਰਹਾ ਨਾਲ ਹੀ ਭਰ ਜਾਏਗਾ ॥੨੬॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[27],"number_text":"੨੭।","page":1885,"lines":[{"gurmukhi":"ਮਤ ਕਰੀ ਤਾ ਕੇ ਪਰ ਡਾਰਿਯੋ। ਸੋ ਤਿਨ ਐਚ ਗਦਾ ਸੋ ਮਾਰਿਯੋ।","roman":"Mat karee taa ke par daariyo | so tin aich gadaa so maariyo |","meaning_en":"A rutting elephant was set upon him; he struck it down with a swing of his mace.","page":1885,"meaning_status":"draft","meaning_pa":"ਉਸ ਉਤੇ ਇਕ ਮਸਤ ਹਾਥੀ ('ਕਰੀ') ਛਡਿਆ ਗਿਆ। ਉਸ ਨੂੰ ਉਸ ਨੇ ਗਦਾ ਖਿਚ ਕੇ ਮਾਰ ਦਿੱਤਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜੋ ਕੋਊ ਸੁਭਟ ਤਵਨ ਪਰ ਧਾਵੈ। ਏਕ ਚੋਟ ਜਮ ਲੋਕ ਪਠਾਵੈ। ੨੭।","roman":"Jo ko'oo subhat tavan par dhaavai | ek chot jam lok pathaavai | 27 |","meaning_en":"Whatever warrior rushed upon him, he sent to the world of Yama with one blow.","page":1885,"meaning_status":"draft","meaning_pa":"ਜੋ ਕੋਈ ਸੂਰਮਾ ਉਸ ਉਤੇ ਹਮਲਾ ਕਰਦਾ ਤਾ ਇਕ ਚੋਟ ਨਾਲ ਹੀ (ਉਸ ਨੂੰ) ਯਮ ਲੋਕ ਵਿਚ ਭੇਜ ਦਿੰਦਾ ॥੨੭॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[28],"number_text":"੨੮।","page":1885,"lines":[{"gurmukhi":"ਰਨ ਤੇ ਏਕ ਪੈਗ ਨਹਿ ਭਾਜੈ। ਠਾਢੋ ਬੀਰ ਖੇਤ ਮੈ ਗਾਜੈ।","roman":"Ran te ek paig nahi bhaajai | thaadho beer khet mai gaajai |","meaning_en":"He did not flee one step from the battle; the hero stood roaring in the field.","page":1885,"meaning_status":"draft","meaning_pa":"(ਉਹ) ਰਣ ਤੋਂ ਇਕ ਕਦਮ ਤਕ ਨਹੀਂ ਭਜਦਾ ਸੀ। (ਉਹ) ਸੂਰਮਾ ਯੁੱਧਭੂਮੀ ਵਿਚ ਖੜੋਤਾ ਗਜਦਾ ਸੀ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਅਧਿਕ ਰਾਵ ਰਾਜਨ ਕੌ ਮਾਰਿਯੋ। ਕਾਪਿ ਸਿਕੰਦਰ ਮੰਤ੍ਰ ਬਿਚਾਰਿਯੋ। ੨੮।","roman":"Adhik raav raajan kau maariyo | kaapi sikandar mantr bichaariyo | 28 |","meaning_en":"He killed many kings and princes; trembling, Sikandar took counsel.","page":1885,"meaning_status":"draft","meaning_pa":"(ਉਸ ਨੇ) ਬਹੁਤ ਸਾਰੇ ਰਾਜਿਆਂ ਰਜਵਾੜਿਆਂ ਨੂੰ (ਜਦ) ਮਾਰ ਦਿੱਤਾ ਤਾ ਸਿਕੰਦਰ ਨੇ (ਡਰ ਨਾਲ) ਕੰਬ ਕੇ ਵਿਚਾਰ ਕੀਤਾ ॥੨੮॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1885,"meaning_status":"draft","meaning_pa":"ਦੋਹਰਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[29],"number_text":"੨੯।","page":1885,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਦਿਨਨਾਥ ਮਤੀ ਤਰੁਨਿ ਸਾਹ ਚੀਨ ਕੇ ਦੀਨ।","roman":"Sree dinnaath matee taruni saah cheen ke deen |","meaning_en":"The young woman Sri Dinnath Mati, whom the Shah of China had given,","page":1885,"meaning_status":"draft","meaning_pa":"ਦਿਨਨਾਥ ਮਤੀ ਨਾ ਦੀ ਇਸਤਰੀ (ਜੋ) ਚੀਨ ਦੇ ਬਾਦਸ਼ਾਹ ਨੇ (ਸਿਕੰਦਰ ਨੂੰ) ਦਿੱਤੀ ਸੀ,","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਸੋ ਤਾ ਪਰ ਧਾਵਤ ਭਈ ਭੇਸ ਪੁਰਖ ਕੋ ਕੀਨ। ੨੯।","roman":"So taa par dhaavat bhaee bhes purakh ko keen | 29 |","meaning_en":"rushed upon him, having put on the dress of a man.","page":1885,"meaning_status":"draft","meaning_pa":"ਉਹ ਪੁਰਸ਼ ਦਾ ਭੇਸ ਧਾਰਨ ਕਰ ਕੇ ਉਸ ਉਤੇ ਟੁੱਟ ਕੇ ਪੈ ਗਈ ॥੨੯॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1885,"meaning_status":"draft","meaning_pa":"ਚੌਪਈ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[30],"number_text":"੩੦।","page":1885,"lines":[{"gurmukhi":"ਪਹਿਲੇ ਤੀਰ ਤਵਨ ਕੌ ਮਾਰੈ। ਬਰਛਾ ਬਹੁਰਿ ਕੋਪ ਤਨ ਝਾਰੈ।","roman":"Pahile teer tavan kau maarai | barchhaa bahuri kop tan jhaarai |","meaning_en":"First she shot arrows at him, then in anger hurled a spear at his body.","page":1885,"meaning_status":"draft","meaning_pa":"ਪਹਿਲਾ ਉਸ ਨੂੰ ਤੀਰ ਮਾਰਿਆ ਅਤੇ ਫਿਰ ਕ੍ਰੋਧਵਾਨ ਹੋ ਕੇ ਉਸ ਦੇ ਸ਼ਰੀਰ ਉਤੇ ਬਰਛੇ ਦਾ ਵਾਰ ਕੀਤਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਤਮਕਿ ਤੇਗ ਕੋ ਘਾਇ ਪ੍ਰਹਾਰਿਯੋ। ਗਿਰਿਯੋ ਭੂਮਿ ਜਾਨੁ ਹਨਿ ਡਾਰਿਯੋ। ੩੦।","roman":"Tamki teg ko ghaai prahaariyo | giriyo bhoomi jaanu hani daariyo | 30 |","meaning_en":"In a flash of fury she struck him a sword-blow; he fell to the ground as if slain.","page":1885,"meaning_status":"draft","meaning_pa":"ਫਿਰ ਰੋਹ ਨਾਲ ਤਲਵਾਰ ਦਾ ਵਾਰ ਕੀਤਾ। (ਜਿਸ ਨਾਲ ਉਹ) ਧਰਤੀ ਉਤੇ ਡਿਗ ਪਿਆ, ਮਾਨੋ ਮਾਰ ਹੀ ਦਿੱਤਾ ਗਿਆ ਹੋਵੇ ॥੩੦॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[31],"number_text":"੩੧।","page":1885,"lines":[{"gurmukhi":"ਭੂ ਪਰ ਗਿਰਿਯੋ ਠਾਢਿ ਉਠਿ ਭਯੋ। ਤਾ ਕੌ ਪਕਰਿ ਕੰਠ ਤੇ ਲਯੋ।","roman":"Bhoo par giriyo thaadhi uthi bhayo | taa kau pakri kanth te layo |","meaning_en":"He fell on the ground, then rose and stood, and seized her by the throat.","page":1885,"meaning_status":"draft","meaning_pa":"(ਉਹ) ਧਰਤੀ ਉਤੇ ਡਿਗਿਆ ਅਤੇ ਫਿਰ ਉਠ ਖੜੋਤਾ। ਉਸ (ਇਸਤਰੀ) ਨੂੰ ਗਲੇ ਤੋਂ ਪਕੜ ਲਿਆ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਸੁੰਦਰ ਬਦਨ ਅਧਿਕ ਤਿਹ ਚੀਨੋ। ਮਾਰਿ ਨ ਦਈ ਰਾਖਿ ਤਿਹ ਲੀਨੋ। ੩੧।","roman":"Sundar badan adhik tih cheeno | maari na daee raakhi tih leeno | 31 |","meaning_en":"He saw that her face was very beautiful; he did not kill her but kept her.","page":1885,"meaning_status":"draft","meaning_pa":"ਉਸ ਦਾ ਬਹੁਤ ਸੁੰਦਰ ਮੁਖ ('ਬਦਨ') ਵੇਖਿਆ (ਤਾ) ਉਸ ਨੂੰ ਮਾਰਿਆ ਨ, ਛਡ ਦਿੱਤਾ ॥੩੧॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[32],"number_text":"੩੨।","page":1885,"lines":[{"gurmukhi":"ਤਾ ਕਹ ਪਕਰਿ ਰੂਸਿਯਨ ਦਯੋ। ਆਪੁ ਉਦਿਤ ਰਨ ਕੋ ਪੁਨਿ ਭਯੋ।","roman":"Taa kah pakri roosiyan dayo | aapu udit ran ko puni bhayo |","meaning_en":"He seized her and gave her to the men of Rus, and himself made ready again for battle.","page":1885,"meaning_status":"draft","meaning_pa":"ਉਸ ਨੂੰ ਪਕੜ ਕੇ ਰੂਸੀਆਂ ਨੂੰ ਦੇ ਦਿੱਤਾ ਅਤੇ ਆਪ ਫਿਰ ਯੁੱਧ ਲਈ ਤਿਆਰ ਹੋ ਗਿਆ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਅਰਿ ਅਮਿਤ ਸੰਘਾਰੈ। ਜਨੁ ਦ੍ਰੁਮ ਪਵਨ ਪ੍ਰਚੰਡ ਉਖਾਰੈ। ੩੨।","roman":"Bhaati bhaati ari amit sanghaarai | janu drum pavan prachand ukhaarai | 32 |","meaning_en":"In many ways he destroyed countless foes, as a fierce wind uproots trees.","page":1885,"meaning_status":"draft","meaning_pa":"(ਉਸ ਨੇ) ਕਈ ਢੰਗਾ ਨਾਲ ਬੇਸ਼ੁਮਾਰ ਵੈਰੀਆਂ ਨੂੰ ਮਾਰ ਦਿੱਤਾ। (ਇੰਜ ਪ੍ਰਤੀਤ ਹੁੰਦਾ ਸੀ) ਮਾਨੋ ਤੇਜ਼ ਹਵਾ ਨੇ ਬ੍ਰਿਛਾ ਨੂੰ ਉਖਾੜ ਸੁਟਿਆ ਹੋਵੇ ॥੩੨॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":1887,"meaning_status":"draft","meaning_pa":"ਸਵੈਯਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[33],"number_text":"੩੩।","page":1887,"lines":[{"gurmukhi":"ਕਾਤੀ ਕ੍ਰਿਪਾਨ ਕਸੇ ਕਟਿ ਮੈ ਭਟ ਭਾਰੀ ਭੁਜਾਨ ਕੌ ਭਾਰ ਭਰੇ ਹੈ।","roman":"Kaatee kripaan kase kati mai bhat bhaaree bhujaan kau bhaar bhare hai |","meaning_en":"Great warriors with dagger and sword girt at the waist, bearing the weight of mighty arms,","page":1887,"meaning_status":"draft","meaning_pa":"ਕਟਾਰ, ਕ੍ਰਿਪਾਨ ਨੂੰ ਲਕ ਨਾਲ ਕਸ ਕੇ ਭਾਰੀ ਭੁਜਾਵਾ ਵਾਲੇ ਸੂਰਮੇ ਬਹੁਤ ਬਲ ਨਾਲ ਭਰੇ ਹੋਏ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਭੂਤ ਭਵਿਖ੍ਯ ਭਵਾਨ ਸਦਾ ਕਬਹੂੰ ਰਨ ਮੰਡਲ ਤੇ ਨ ਟਰੇ ਹੈ।","roman":"Bhoot bhavikhy bhavaan sadaa kabhoon ran mandal te na tare hai |","meaning_en":"who in past, future and present had never once moved from the field of battle,","page":1887,"meaning_status":"draft","note":"ਭਵਾਨ: read as 'the present'; uncertain.","meaning_pa":"ਭੂਤ, ਭਵਿਖਤ ਅਤੇ ਵਰਤਮਾਨ ਕਾਲਾ ਵਿਚ ਕਦੇ ਵੀ ਯੁੱਧ-ਭੂਮੀ ਵਿਚੋਂ ਹਟੇ ਨਹੀਂ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਭੀਰ ਪਰੇ ਨਹਿ ਭੀਰ ਭੇ ਭੂਪਤਿ ਲੈ ਲੈ ਭਲਾ ਭਲੀ ਭਾਤਿ ਅਰੇ ਹੈ।","roman":"Bheer pare nahi bheer bhe bhoopti lai lai bhalaa bhalee bhaati are hai |","meaning_en":"kings who knew no fear when hard pressed, who took up their spears and stood firm and well:","page":1887,"meaning_status":"draft","note":"ਭਲਾ: read as ਭਾਲਾ, 'spear'; uncertain.","meaning_pa":"ਭੀੜ ਪੈਣ ਤੇ ਇਹ ਰਾਜੇ ਡਰਦੇ ਨਹੀਂ, ਸਗੋਂ ਭਾਲੇ ਲੈ ਲੈ ਕੇ ਚੰਗੀ ਤਰ੍ਰਹਾ ਡੱਟੇ ਰਹਿੰਦੇ ਹਨ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਤੇ ਇਨ ਬੀਰ ਮਹਾ ਰਨਧੀਰ ਸੁ ਹਾਕਿ ਹਜਾਰ ਅਨੇਕ ਹਰੇ ਹੈ। ੩੩।","roman":"Te in beer mahaa randheer su haaki hajaar anek hare hai | 33 |","meaning_en":"these heroes, most steadfast in battle, he challenged and destroyed in many thousands.","page":1887,"meaning_status":"draft","meaning_pa":"ਇਸ ਮਹਾਨ ਯੋਧੇ ਨੇ ਹਜ਼ਾਰਾ ਨੂੰ ਵੰਗਾਰ ਵੰਗਾਰ ਕੇ ਮਾਰ ਦਿੱਤਾ ਹੈ ॥੩੩॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1887,"meaning_status":"draft","meaning_pa":"ਚੌਪਈ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[34],"number_text":"੩੪।","page":1887,"lines":[{"gurmukhi":"ਤਬ ਹੀ ਸਾਹ ਸਕੰਦਰ ਡਰਿਯੋ। ਬੋਲਿ ਅਰਸਤੂ ਮੰਤ੍ਰ ਬਿਚਰਿਯੋ।","roman":"Tab hee saah sakandar dariyo | boli arastoo mantr bichriyo |","meaning_en":"Then Shah Sikandar was afraid; he called Arastu and took counsel.","page":1887,"meaning_status":"draft","note":"ਅਰਸਤੂ: Aristotle.","meaning_pa":"ਤਦ ਸਿਕੰਦਰ ਬਾਦਸ਼ਾਹ ਡਰ ਗਿਆ ਅਤੇ ਅਰਸਤੂ ਨੂੰ ਬੁਲਾ ਕੇ ਸਲਾਹ ਕੀਤੀ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਬਲੀ ਨਾਸ ਕੋ ਬੋਲਿ ਪਠਾਯੋ। ਚਿਤ ਮੈ ਅਧਿਕ ਤ੍ਰਾਸ ਉਪਜਾਯੋ। ੩੪।","roman":"Balee naas ko boli pathaayo | chit mai adhik traas upjaayo | 34 |","meaning_en":"He sent for Balinas, great dread having arisen in his heart:","page":1887,"meaning_status":"draft","note":"ਬਲੀ ਨਾਸ: Balinas (Apollonius), the sage of the Sikandar legend.","meaning_pa":"ਬਲੀ ਨਾਸ (ਨਾ ਦੇ ਦੈਂਤ) ਨੂੰ ਬੁਲਾ ਲਿਆ ਚਿਤ ਵਿਚ ਬਹੁਤ ਡਰ ਪੈਦਾ ਹੋ ਜਾਣ ਕਾਰਨ ॥੩੪॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":1887,"meaning_status":"draft","meaning_pa":"ਅੜਿਲ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[35],"number_text":"੩੫।","page":1887,"lines":[{"gurmukhi":"ਜੋ ਤੁਮ ਹਮ ਕੌ ਕਹੋ ਤੋ ਹ੍ਯਾ ਤੈ ਭਾਜਿਯੈ।","roman":"Jo tum ham kau kaho to hyaa tai bhaajiyai |","meaning_en":"'If you tell me to, let us flee from here","page":1887,"meaning_status":"draft"},{"gurmukhi":"ਰੂਸ ਸਹਿਰ ਕੇ ਭੀਤਰਿ ਜਾਇ ਬਿਰਾਜਿਯੈ।","roman":"Roos sahir ke bheetri jaai biraajiyai |","meaning_en":"and go and stay within the city of Rus.","page":1887,"meaning_status":"draft","note":"Translated as printed; the sense of fleeing into the city of Rus is unclear.","meaning_pa":"ਜੇ ਤੁਸੀਂ ਮੈਨੂੰ ਕਹੋ ਤਾ (ਮੈਂ) ਇਥੋਂ ਭਜ ਜਾਵਾ ਅਤੇ ਰੂਸ ਸ਼ਹਿਰ ਦੇ ਵਿਚ ਜਾ ਰਹਾ।","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"},{"gurmukhi":"ਗੋਲ ਬ੍ਯਾਬਾਨੀ ਮੈ ਸਭ ਹੀ ਕੌ ਮਾਰਿ ਹੈ।","roman":"Gol byaabaanee mai sabh hee kau maari hai |","meaning_en":"This ghoul of the wilderness will kill us all,","page":1887,"meaning_status":"draft","note":"ਗੋਲ ਬ੍ਯਾਬਾਨੀ: Persian ghul-i-biyabani, 'ghoul/demon of the desert'."},{"gurmukhi":"ਹੋ ਕਾਟਿ ਕਾਟਿ ਮੂੰਡਨ ਕੇ ਕੋਟ ਉਸਾਰਿ ਹੈ। ੩੫।","roman":"Ho kaati kaati moondan ke kot usaari hai | 35 |","meaning_en":"and cutting off heads will build ramparts of them.'","page":1887,"meaning_status":"draft","meaning_pa":"(ਇਹ) ਮ੍ਰਿਗ ਤ੍ਰਿਸਨਾ ਵਾਲਾ ਮਰੁਸਥਲੀ ਛਲਾਵਾ (ਸਾਨੂੰ) ਸਾਰਿਆਂ ਨੂੰ (ਭਜਾ ਭਜਾ ਕੇ) ਮਾਰ ਦੇਵੇਗਾ ਅਤੇ ਸਿਰਾ ਨੂੰ ਕਟ ਕਟ ਕੇ ਕਿਲਾ ਬਣਾ ਦੇਵੇਗਾ ॥੩੫॥","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1887,"meaning_status":"draft","meaning_pa":"ਦੋਹਰਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[36],"number_text":"੩੬।","page":1887,"lines":[{"gurmukhi":"ਬਲੀ ਨਾਸ ਜੋਤਕ ਬਿਖੈ ਅਧਿਕ ਹੁਤੋ ਪਰਬੀਨ।","roman":"Balee naas jotak bikhai adhik huto parbeen |","meaning_en":"Balinas was highly skilled in astrology;","page":1887,"meaning_status":"draft","meaning_pa":"ਬਲੀ ਨਾਸ ਜੋਤਿਸ਼ ਵਿਚ ਬਹੁਤ ਪ੍ਰਬੀਨ ਸੀ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਧੀਰਜ ਦੀਯਾ ਸਕੰਦਰਹਿ ਬਿਜੈ ਆਪਨੀ ਚੀਨ। ੩੬।","roman":"Dheeraj deeyaa sakandarhi bijai aapnee cheen | 36 |","meaning_en":"he gave Sikandar courage, discerning that the victory would be his.","page":1887,"meaning_status":"draft","meaning_pa":"(ਉਸ ਨੇ) ਆਪਣੀ ਜਿਤ ਪਛਾਣ ਕੇ (ਵੇਖ ਕੇ) ਸਿਕੰਦਰ ਨੂੰ ਧੀਰਜ ਦਿੱਤਾ ॥੩੬॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1887,"meaning_status":"draft","meaning_pa":"ਚੌਪਈ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[37],"number_text":"੩੭।","page":1887,"lines":[{"gurmukhi":"ਬਲੀ ਨਾਸ ਹਜਰਤਿਹਿ ਉਚਾਰੋ। ਤੁਮਹੂੰ ਆਪੁ ਕਮੰਦਹਿ ਡਾਰੋ।","roman":"Balee naas hajartihi uchaaro | tumhoon aapu kamandhi daaro |","meaning_en":"Balinas said to His Majesty, 'You yourself throw the lasso.","page":1887,"meaning_status":"draft","note":"ਹਜਰਤਿ: 'His Majesty', Sikandar. ਕਮੰਦ: lasso, noose.","meaning_pa":"ਬਲੀ ਨਾਸ ਨੇ ਬਾਦਸ਼ਾਹ ਨੂੰ ਕਿਹਾ ਕਿ ਤੂੰ ਆਪ (ਉਸ ਦੇ ਗਲ ਵਿਚ) ਫਾਹੀ ਪਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਤੁਮਰੇ ਬਿਨਾ ਜੀਤਿ ਨਹਿ ਹੋਈ। ਅਮਿਤਿ ਸੁਭਟ ਧਾਵਹਿੰ ਮਿਲਿ ਕੋਈ। ੩੭।","roman":"Tumre binaa jeeti nahi hoee | amiti subhat dhaavhin mili koee | 37 |","meaning_en":"Without you there will be no victory, though countless warriors rush at him together.'","page":1887,"meaning_status":"draft","meaning_pa":"ਤੇਰੇ (ਅਜਿਹਾ ਕੀਤੇ ਬਿਨਾ) ਜਿਤ ਨਹੀਂ ਹੋ ਸਕੇਗੀ, ਭਾਵੇਾਂ ਬੇਸ਼ੁਮਾਰ ਸੂਰਮੇ ਮਿਲ ਕੇ ਹਮਲਾ ਕਿਉਾਂ ਨਾ ਕਰਨ ॥੩੭॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1887,"meaning_status":"draft","meaning_pa":"ਦੋਹਰਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[38],"number_text":"੩੮।","page":1887,"lines":[{"gurmukhi":"ਸੁਨਤ ਸਿਕੰਦਰ ਏ ਬਚਨ ਕਰਿਯੋ ਤੈਸੋਈ ਕਾਮ।","roman":"Sunat sikandar e bachan kariyo taisoee kaam |","meaning_en":"Hearing these words Sikandar did just that:","page":1887,"meaning_status":"draft","meaning_pa":"ਸਿਕੰਦਰ ਨੇ ਇਹ ਗੱਲ ਸੁਣ ਕੇ ਉਹੋ ਜਿਹਾ ਹੀ ਕੰਮ ਕੀਤਾ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਕਮੰਦ ਡਾਰਿ ਤਾ ਕੋ ਗਰੇ ਬਾਂਧ ਲਿਆਇਯੋ ਧਾਮ। ੩੮।","roman":"Kamand daari taa ko gare baandh liaaiyo dhaam | 38 |","meaning_en":"throwing the lasso on his neck, he bound him and brought him to his quarters.","page":1887,"meaning_status":"draft","meaning_pa":"ਉਸ ਦੇ ਗਲੇ ਵਿਚ ਫਾਹੀ ਪਾ ਕੇ ਘਰ (ਠਿਕਾਣੇ) ਨੂੰ ਬੰਨ੍ਰਹ ਲਿਆਂਦਾ ॥੩੮॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":1887,"meaning_status":"draft","meaning_pa":"ਅੜਿਲ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[39],"number_text":"੩੯।","page":1887,"lines":[{"gurmukhi":"ਭੋਜਨ ਸਾਹਿ ਭਲੀ ਬਿਧਿ ਤਾਹਿ ਖਵਾਇਯੋ।","roman":"Bhojan saahi bhalee bidhi taahi khavaaiyo |","meaning_en":"The Shah fed him well with food,","page":1887,"meaning_status":"draft","meaning_pa":"ਬਾਦਸ਼ਾਹ ਨੇ ਉਸ ਨੂੰ ਚੰਗੀ ਤਰ੍ਰਹਾ ਭੋਜਨ ਖਵਾਇਆ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਬੰਧਨ ਤਾ ਕੇ ਕਾਟਿ ਭਲੇ ਬੈਠਾਇਯੋ।","roman":"Bandhan taa ke kaati bhale baithaaiyo |","meaning_en":"cut his bonds and seated him kindly.","page":1887,"meaning_status":"draft","meaning_pa":"ਉਸ ਦੇ ਬੰਧਨ ਕਟ ਕੇ ਉਸ ਨੂੰ ਚੰਗੀ ਤਰ੍ਰਹਾ ਬਿਠਾਇਆ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਛੂਟਤ ਬੰਧਨ ਭਜ੍ਯੋ ਤਹਾ ਹੀ ਕੋ ਗਯੋ।","roman":"Chhootat bandhan bhajyo tahaa hee ko gayo |","meaning_en":"As soon as his bonds were loosed he ran off and went back there,","page":1887,"meaning_status":"draft","meaning_pa":"ਬੰਧਨਾ ਤੋਂ ਖ਼ਲਾਸ ਹੁੰਦਿਆਂ ਹੀ ਉਹ ਉਥੇ ਭਜ ਕੇ ਗਿਆ","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਹੋ ਆਨਿ ਲੌਂਡਿਯਹਿ ਬਹੁਰਿ ਸਿਕੰਦਰ ਕੌ ਦਯੋ। ੩੯।","roman":"Ho aani laundiyhi bahuri sikandar kau dayo | 39 |","meaning_en":"and brought the slave-girl and gave her back to Sikandar.","page":1887,"meaning_status":"draft","meaning_pa":"ਅਤੇ ਇਸਤਰੀ (ਲੌਂਡੀ) ਨੂੰ ਲਿਆ ਕੇ ਫਿਰ ਸਿਕੰਦਰ ਨੂੰ ਆਣ ਦਿੱਤਾ ॥੩੯॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1887,"meaning_status":"draft","meaning_pa":"ਦੋਹਰਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[40],"number_text":"੪੦।","page":1887,"lines":[{"gurmukhi":"ਤਾ ਕੋ ਰੂਪ ਬਿਲੋਕਿ ਕੈ ਹਜਰਤਿ ਰਹਿਯੋ ਲੁਭਾਇ।","roman":"Taa ko roop biloki kai hajarti rahiyo lubhaai |","meaning_en":"Seeing her beauty His Majesty was captivated;","page":1887,"meaning_status":"draft","meaning_pa":"ਉਸ (ਇਸਤਰੀ) ਦਾ ਰੂਪ ਵੇਖ ਕੇ ਸਿਕੰਦਰ ਮੋਹਿਤ ਹੋ ਗਿਆ","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਲੈ ਆਪੁਨੀ ਇਸਤ੍ਰੀ ਕਰੀ ਢੋਲ ਮ੍ਰਿਦੰਗ ਬਜਾਇ। ੪੦।","roman":"Lai aapunee istree karee dhol mridang bajaai | 40 |","meaning_en":"he took her and made her his wife to the sound of dhol and mridang drums.","page":1887,"meaning_status":"draft","meaning_pa":"ਅਤੇ ਢੋਲ ਮ੍ਰਿਦੰਗ ਵਜਾ ਕੇ ਉਸ ਨੂੰ ਆਪਣੀ ਇਸਤਰੀ ਬਣਾ ਲਿਆ ॥੪੦॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[41],"number_text":"੪੧।","page":1887,"lines":[{"gurmukhi":"ਬਹੁਰਿ ਜਹਾ ਅੰਮ੍ਰਿਤ ਸੁਨ੍ਯੋ ਗਯੋ ਤਵਨ ਕੀ ਓਰ।","roman":"Bahuri jahaa anmrit sunyo gayo tavan kee or |","meaning_en":"Then he went towards the place where he had heard the nectar was,","page":1887,"meaning_status":"draft","meaning_pa":"ਫਿਰ ਜਿਥੇ ਅੰਮ੍ਰਿਤ-ਕੁੰਡ ਸੁਣਿਆ ਸੀ, ਉਧਰ ਵਲ ਚਲ ਪਿਆ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਕਰਿ ਇਸਤ੍ਰੀ ਚੇਰੀ ਲਈ ਔਰ ਬੇਗਮਨ ਛੋਰਿ। ੪੧।","roman":"Kari istree cheree laee aur begman chhori | 41 |","meaning_en":"taking the slave-girl he had made his wife and leaving the other begums.","page":1887,"meaning_status":"draft","meaning_pa":"(ਉਸ ਨੇ) ਦਾਸੀ ਨੂੰ ਇਸਤਰੀ ਬਣਾ ਲਿਆ ਅਤੇ ਹੋਰਨਾ ਬੇਗਮਾ ਨੂੰ ਛਡ ਦਿੱਤਾ ॥੪੧॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1889,"meaning_status":"draft","meaning_pa":"ਚੌਪਈ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[42],"number_text":"੪੨।","page":1889,"lines":[{"gurmukhi":"ਜੁ ਤ੍ਰਿਯ ਰੈਨਿ ਕੌ ਸੇਜ ਸੁਹਾਵੈ। ਦਿਵਸ ਬੈਰਿਯਨ ਖੜਗ ਬਜਾਵੈ।","roman":"Ju triy raini kau sej suhaavai | divas bairiyan kharag bajaavai |","meaning_en":"A woman who graces the bed by night and by day plies the sword on enemies:","page":1889,"meaning_status":"draft","meaning_pa":"ਜੋ ਇਸਤਰੀ ਰਾਤ ਨੂੰ ਸੇਜ ਨੂੰ ਸੁਸ਼ੋਭਿਤ ਕਰਦੀ ਹੈ ਅਤੇ ਦਿਨ ਨੂੰ ਵੈਰੀਆਂ ਨਾਲ ਤਲਵਾਰ ਚਲਾਉਾਂਦੀ ਹੈ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਐਸੀ ਤਰੁਨਿ ਕਰਨ ਜੌ ਪਰਈ। ਤਿਹ ਤਜਿ ਔਰ ਕਵਨ ਚਿਤ ਕਰਈ। ੪੨।","roman":"Aisee taruni karan jau paraee | tih taji aur kavan chit karaee | 42 |","meaning_en":"if such a young woman comes into one's hands, who would leave her and set his heart on another?","page":1889,"meaning_status":"draft","meaning_pa":"ਅਜਿਹੀ ਇਸਤਰੀ ਜੇ ਹੱਥ ਲਗ ਜਾਵੇ, ਤਾ ਉਸ ਨੂੰ ਛਡ ਕੇ ਕਿਸੇ ਹੋਰ ਨੂੰ ਚਿਤ ਵਿਚ (ਕਿਉਾਂ) ਲਿਆਇਆ ਜਾਏ ॥੪੨॥","meaning_pa_source":"BaniDB"}]},{"type":"verse","number":[43],"number_text":"੪੩।","page":1889,"lines":[{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਤਾ ਸੋ ਰਤਿ ਠਾਨੀ। ਚੇਰੀ ਤੇ ਬੇਗਮ ਕਰਿ ਜਾਨੀ।","roman":"Bhaati bhaati taa so rati thaanee | cheree te begam kari jaanee |","meaning_en":"He made love with her in many ways and from a slave came to regard her as a begum.","page":1889,"meaning_status":"draft","meaning_pa":"ਉਸ (ਇਸਤਰੀ) ਨਾਲ ਭਾਤ ਭਾਤ ਦੀ ਰਤੀ-ਕ੍ਰੀੜਾ ਕੀਤੀ। (ਉਸ) ਨੂੰ ਦਾਸੀ ਤੋਂ ਬੇਗਮ ਕਰ ਲਿਆ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਤਾ ਕੌ ਸੰਗ ਆਪੁਨੇ ਲਯੋ। ਆਬਹਯਾਤ ਸੁਨ੍ਯੋ ਤਹ ਗਯੋ। ੪੩।","roman":"Taa kau sang aapune layo | aabahyaat sunyo tah gayo | 43 |","meaning_en":"He took her along with him and went where he had heard the water of life was.","page":1889,"meaning_status":"draft","note":"ਆਬਹਯਾਤ: Persian ab-i-hayat, 'the water of life'.","meaning_pa":"ਉਸ ਨੂੰ ਆਪਣੇ ਨਾਲ ਲੈ ਲਿਆ ਅਤੇ ਜਿਥੇ ਅੰਮ੍ਰਿਤ ('ਆਬਹਯਾਤ') ਸੁਣਿਆ ਸੀ, ਉਥੇ ਜਾ ਪਹੁੰਚਿਆ ॥੪੩॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1889,"meaning_status":"draft","meaning_pa":"ਦੋਹਰਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[44],"number_text":"੪੪।","page":1889,"lines":[{"gurmukhi":"ਜਹ ਤਾ ਕੌ ਚਸਮਾ ਹੁਤੋ ਤਹੀ ਪਹੂਚੋ ਜਾਇ।","roman":"Jah taa kau chasmaa huto tahee pahoocho jaai |","meaning_en":"He went and reached the place where its spring was,","page":1889,"meaning_status":"draft","meaning_pa":"ਜਿਥੇ ਉਸ (ਅੰਮ੍ਰਿਤ) ਦਾ ਚਸ਼ਮਾ ਸੀ ਉਥੇ ਹੀ ਜਾ ਪਹੁੰਚਿਆ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਮਕਰ ਕੁੰਟ ਜਹ ਡਾਰਿਯੈ ਮਛਲੀ ਹੋਇ ਬਨਾਇ। ੪੪।","roman":"Makar kunt jah daariyai machhlee hoi banaai | 44 |","meaning_en":"where, if a piece of fish is thrown in, it becomes a whole fish.","page":1889,"meaning_status":"draft","note":"ਮਕਰ ਕੁੰਟ: read as 'a piece of fish/sea-creature'; ਕੁੰਟ is uncertain.","meaning_pa":"ਜੇ ਉਸ ਕੁੰਡ ਵਿਚ ਮਗਰਮਛ ਸੁਟ ਦੇਈਏ ਤਾ ਉਹ ਮਛਲੀ ਬਣ ਜਾਦਾ ਹੈ ॥੪੪॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1889,"meaning_status":"draft","meaning_pa":"ਚੌਪਈ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[45],"number_text":"੪੫।","page":1889,"lines":[{"gurmukhi":"ਇੰਦ੍ਰ ਦੇਵ ਤਬ ਮੰਤ੍ਰ ਬਤਾਯੋ। ਅੰਮ੍ਰਿਤ ਸਾਹ ਸਿਕੰਦਰ ਪਾਯੋ।","roman":"Indr dev tab mantr bataayo | anmrit saah sikandar paayo |","meaning_en":"Then the matter was laid before the god Indra: 'Shah Sikandar has found the nectar.","page":1889,"meaning_status":"draft","note":"ਇੰਦ੍ਰ ਦੇਵ ਤਬ ਮੰਤ੍ਰ ਬਤਾਯੋ: could also be 'then the god Indra gave counsel'; uncertain.","meaning_pa":"ਇੰਦਰ ਦੇਵ ਨੂੰ ਤਦ ਦੇਵਤਿਆਂ ਨੇ ਦਸਿਆ ਕਿ ਸਿਕੰਦਰ ਬਾਦਸ਼ਾਹ ਨੇ ਅੰਮ੍ਰਿਤ ਲਭ ਲਿਆ ਹੈ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਅਜਰ ਅਮਰ ਮਨੁਖ੍ਯ ਜੋ ਹ੍ਵੈ ਹੈ। ਜੀਤਿ ਸੁ ਲੋਕ ਚੌਦਹੂੰ ਲੈਹੈ। ੪੫।","roman":"Ajar amar manukhy jo hvai hai | jeeti su lok chaudhoon laihai | 45 |","meaning_en":"If a man becomes ageless and deathless, he will conquer and take the fourteen worlds.","page":1889,"meaning_status":"draft","meaning_pa":"ਜੇ ਮਨੁੱਖ ਅਜਰ ਅਮਰ ਹੋ ਜਾਵੇਗਾ (ਤਾ ਉਹ) ਚੌਦਾ ਲੋਕਾ ਨੂੰ ਜਿਤ ਲਏਗਾ ॥੪੫॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1889,"meaning_status":"draft","meaning_pa":"ਦੋਹਰਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[46],"number_text":"੪੬।","page":1889,"lines":[{"gurmukhi":"ਤਾ ਤੇ ਯਾ ਕੋ ਕੀਜਿਯੈ ਕਛੁ ਉਪਚਾਰ ਬਨਾਇ।","roman":"Taa te yaa ko keejiyai kachhu upchaar banaai |","meaning_en":"Therefore let some remedy be devised for him,","page":1889,"meaning_status":"draft","meaning_pa":"ਇਸ ਲਈ ਇਸ ਦਾ ਕੋਈ ਉਪਾ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਜਿਤ੍ਯੋ ਜਰਾ ਤਨ ਜੜ ਰਹੈ ਅੰਮ੍ਰਿਤ ਪਿਯੌ ਨ ਜਾਇ। ੪੬।","roman":"Jityo jaraa tan jar rahai anmrit piyau na jaai | 46 |","meaning_en":"so that the fool's body stays subject to old age and the nectar is not drunk.'","page":1889,"meaning_status":"draft","note":"ਜਿਤ੍ਯੋ ਜਰਾ ਤਨ ਜੜ ਰਹੈ: read as 'the fool remains with a body conquered by old age'; uncertain.","meaning_pa":"ਜਿਸ ਨਾਲ ਇਸ ਮੂਰਖ ਦਾ ਸ਼ਰੀਰ ਬੁੱਢਾ ਹੋ ਜਾਏ ਅਤੇ ਅੰਮ੍ਰਿਤ ਪੀਤਾ ਨਾ ਜਾ ਸਕੇ ॥੪੬॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":1889,"meaning_status":"draft","meaning_pa":"ਅੜਿਲ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[47],"number_text":"੪੭।","page":1889,"lines":[{"gurmukhi":"ਰੰਭਾ ਨਾਮ ਅਪਛਰਾ ਦਈ ਪਠਾਇ ਕੈ।","roman":"Ranbhaa naam apachhraa daee pathaai kai |","meaning_en":"He sent the apsara named Rambha,","page":1889,"meaning_status":"draft","meaning_pa":"ਇੰਦਰ ਨੇ ਰੰਭਾ ਨਾ ਦੀ ਅਪੱਛਰਾ ਨੂੰ ਭੇਜਿਆ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਬਿਰਧ ਰੂਪ ਖਗ ਕੋ ਧਰਿ ਬੈਠੀ ਆਇ ਕੈ।","roman":"Biradh roop khag ko dhari baithee aai kai |","meaning_en":"who took the form of an aged bird and came and sat there.","page":1889,"meaning_status":"draft","meaning_pa":"ਜੋ ਇਕ ਬੁੱਢੇ ਪੰਛੀ ਦਾ ਰੂਪ ਧਾਰ ਕੇ (ਕੁੰਡ ਦੇ ਨੇੜੇ) ਆ ਬੈਠੀ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਏਕ ਪੰਖ ਤਨ ਰਹਿਯੋ ਨ ਤਾ ਕੌ ਜਾਨਿਯੈ।","roman":"Ek pankh tan rahiyo na taa kau jaaniyai |","meaning_en":"Know that not one feather remained on her body,","page":1889,"meaning_status":"draft","meaning_pa":"ਉਸ ਦੇ ਸ਼ਰੀਰ ਉਤੇ ਇਕ ਖੰਭ ਵੀ ਰਿਹਾ ਹੋਇਆ ਨਾ ਸਮਝੋ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਹੋ ਜਾ ਤਨ ਲਹਿਯੋ ਨ ਜਾਇ ਘ੍ਰਿਣਾ ਜਿਯ ਠਾਨਿਯੈ। ੪੭।","roman":"Ho jaa tan lahiyo na jaai ghrinaa jiy thaaniyai | 47 |","meaning_en":"a body that could not be looked at, and that filled the heart with disgust.","page":1889,"meaning_status":"draft","meaning_pa":"ਉਸ ਦੇ ਸ਼ਰੀਰ ਨੂੰ ਵੇਖਿਆ ਨਹੀਂ ਜਾ ਸਕਦਾ, ਮਨ ਵਿਚ ਘਿਰਨਾ ਪੈਦਾ ਹੋ ਜਾਦੀ ਹੈ ॥੪੭॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1889,"meaning_status":"draft","meaning_pa":"ਦੋਹਰਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[48],"number_text":"੪੮।","page":1889,"lines":[{"gurmukhi":"ਜਬੈ ਸਿਕੰਦਰ ਅੰਮ੍ਰਿਤ ਕੋ ਪੀਵਨ ਲਗ੍ਯੋ ਬਨਾਇ।","roman":"Jabai sikandar anmrit ko peevan lagyo banaai |","meaning_en":"When Sikandar was just about to drink the nectar,","page":1889,"meaning_status":"draft","meaning_pa":"ਜਦ ਸਿਕੰਦਰ ਅੰਮ੍ਰਿਤ ਨੂੰ ਪੀਣ ਲਗਿਆ,","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਗਲਤ ਅੰਗ ਪੰਛੀ ਤਬੈ ਨਿਰਖਿ ਉਠਿਯੋ ਮੁਸਕਾਇ। ੪੮।","roman":"Galat ang panchhee tabai nirkhi uthiyo muskaai | 48 |","meaning_en":"the bird with wasted limbs saw it and broke into a smile.","page":1889,"meaning_status":"draft","meaning_pa":"ਤਾ ਉਹ ਗਲੇ ਹੋਏ ਸ਼ਰੀਰ ਵਾਲਾ ਪੰਛੀ ਵੇਖ ਕੇ ਹੱਸ ਪਿਆ ॥੪੮॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1889,"meaning_status":"draft","meaning_pa":"ਚੌਪਈ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[49],"number_text":"੪੯।","page":1889,"lines":[{"gurmukhi":"ਪੂਛਿਯੋ ਤਾਹਿ ਪੰਛਿਯਹਿ ਜਾਈ। ਕ੍ਯੋ ਤੈ ਹਸ੍ਯੋ ਹੇਰਿ ਮੁਹਿ ਭਾਈ।","roman":"Poochhiyo taahi panchhiyhi jaaee | kyo tai hasyo heri muhi bhaaee |","meaning_en":"He went and asked the bird, 'Why did you laugh on seeing me, brother?","page":1889,"meaning_status":"draft","meaning_pa":"(ਸਿਕੰਦਰ ਨੇ) ਉਸ ਪੰਛੀ ਨੂੰ ਜਾ ਕੇ ਪੁਛਿਆ, ਹੇ ਭਰਾ! (ਤੂੰ) ਮੈਨੂੰ ਵੇਖ ਕੇ ਕਿਉਾਂ ਹਸਿਆ ਹੈਂ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਸਕਲ ਬ੍ਰਿਥਾ ਵਹੁ ਮੋਹਿ ਬਤੈਯੈ। ਹਮਰੇ ਚਿਤ ਕੋ ਤਾਪ ਮਿਟੈਯੈ। ੪੯।","roman":"Sakal brithaa vahu mohi bataiyai | hamre chit ko taap mitaiyai | 49 |","meaning_en":"Tell me the whole story and take away the distress of my heart.'","page":1889,"meaning_status":"draft","meaning_pa":"ਉਹ ਸਾਰੀ ਗੱਲ ਮੈਨੂੰ ਦਸ ਅਤੇ ਮੇਰੇ ਮਨ ਦਾ ਦੁਖ ਦੂਰ ਕਰ ॥੪੯॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"speaker","name":"ਪੰਛੀ ਬਾਚ","gurmukhi":"ਪੰਛੀ ਬਾਚ","roman":"Panchhee baach","meaning_en":"The bird said:","page":1889,"meaning_status":"draft","meaning_pa":"ਪੰਛੀ ਨੇ ਕਿਹਾ:","meaning_pa_source":"BaniDB"},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1889,"meaning_status":"draft","meaning_pa":"ਦੋਹਰਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[50],"number_text":"੫੦।","page":1889,"lines":[{"gurmukhi":"ਪਛ ਏਕ ਤਨ ਨ ਰਹਿਯੋ ਰਕਤ ਨ ਰਹਿਯੋ ਸਰੀਰ।","roman":"Pachh ek tan na rahiyo rakat na rahiyo sareer |","meaning_en":"'Not one feather is left on my body, no blood is left in my frame;","page":1889,"meaning_status":"draft","meaning_pa":"(ਮੇਰੇ) ਤਨ ਉਤੇ ਇਕ ਖੰਭ ਵੀ ਨਹੀਂ ਰਿਹਾ ਅਤੇ ਨਾ ਹੀ ਸ਼ਰੀਰ ਵਿਚ ਲਹੂ ਰਿਹਾ ਹੈ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਤਨ ਨ ਛੁਟਤ ਦੁਖ ਸੌ ਜਿਯਤ ਜਬ ਤੇ ਪਿਯੋ ਕੁਨੀਰ। ੫੦।","roman":"Tan na chhutat dukh sau jiyat jab te piyo kuneer | 50 |","meaning_en":"the body does not leave me and I live in pain, ever since I drank this evil water.","page":1889,"meaning_status":"draft","note":"ਕੁਨੀਰ: 'bad water'.","meaning_pa":"ਸ਼ਰੀਰ ਖ਼ਲਾਸ ਨਹੀਂ ਹੁੰਦਾ ਅਤੇ ਦੁਖ ਨਾਲ ਜੀ ਰਿਹਾ ਹਾ ਜਦ ਦਾ (ਮੈਂ) ਇਹ ਭੈੜਾ ਜਲ ਪੀ ਲਿਆ ਹੈ ॥੫੦॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1891,"meaning_status":"draft","meaning_pa":"ਚੌਪਈ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[51],"number_text":"੫੧।","page":1891,"lines":[{"gurmukhi":"ਭਲਾ ਭਯੋ ਅੰਮ੍ਰਿਤ ਯਹ ਪੀਹੈ। ਹਮਰੀ ਭਾਤਿ ਬਹੁਤ ਦਿਨ ਜੀਹੈ।","roman":"Bhalaa bhayo anmrit yah peehai | hamree bhaati bahut din jeehai |","meaning_en":"It is well that this one will drink the nectar; he will live many days as I do.'","page":1891,"meaning_status":"draft","meaning_pa":"ਚੰਗਾ ਹੋਵੇ ਜੇ (ਤੁਸੀਂ ਇਹ) ਅੰਮ੍ਰਿਤ ਪੀ ਲਵੋ। ਮੇਰੇ ਵਾਗ ਬਹੁਤ ਸਮੇਾਂ ਤਕ ਜੀਉਾਂਦੇ ਰਹੋ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਸੁਨਿ ਏ ਬਚਨ ਸਿਕੰਦਰ ਡਰਿਯੋ। ਪਿਯਤ ਹੁਤੋ ਮਧੁ ਪਾਨ ਨ ਕਰਿਯੋ। ੫੧।","roman":"Suni e bachan sikandar dariyo | piyat huto madhu paan na kariyo | 51 |","meaning_en":"Hearing these words Sikandar was afraid; he had been about to drink it but did not drink the nectar.","page":1891,"meaning_status":"draft","note":"ਮਧੁ: here the nectar.","meaning_pa":"ਸਿਕੰਦਰ ਇਹ ਗੱਲ ਸੁਣ ਕੇ ਬਹੁਤ ਡਰਿਆ। ਅੰਮ੍ਰਿਤ ਨੂੰ ਪੀਣ ਲਗਿਆ ਸੀ, ਪਰ ਨਾ ਪੀਤਾ ॥੫੧॥","meaning_pa_source":"BaniDB"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1891,"meaning_status":"draft","meaning_pa":"ਦੋਹਰਾ:","meaning_pa_source":"BaniDB"},{"type":"verse","number":[52,1],"number_text":"੫੨। ੧।","page":1891,"lines":[{"gurmukhi":"ਅਛਲ ਛੈਲ ਛੈਲੀ ਛਲ੍ਯੋ ਇਹ ਚਰਿਤ੍ਰ ਕੇ ਸੰਗ।","roman":"Achhal chhail chhailee chhalyo ih charitr ke sang |","meaning_en":"The lady deceived the undeceivable gallant with this stratagem;","page":1891,"meaning_status":"draft","meaning_pa":"ਨ ਛਲੇ ਜਾ ਸਕਣ ਵਾਲੇ ਛੈਲ (ਭਾਵ ਸਿਕੰਦਰ) ਨੂੰ ਇਸਤਰੀ ਨੇ ਇਹ ਚਰਿਤ੍ਰ ਕਰ ਕੇ ਛਲ ਲਿਆ।","meaning_pa_source":"BaniDB"},{"gurmukhi":"ਸੁ ਕਬਿ ਕਾਲ ਤਬ ਹੀ ਭਯੋ ਪੂਰਨ ਕਥਾ ਪ੍ਰਸੰਗ। ੫੨। ੧।","roman":"Su kabi kaal tab hee bhayo pooran kathaa prasang | 52 | 1 |","meaning_en":"the poet Kal says, just then the telling of the tale was complete.","page":1891,"meaning_status":"draft","note":"ਸੁ ਕਬਿ ਕਾਲ: 'the good poet Kal'; could also be read 'at that very time'; uncertain.","meaning_pa":"ਕਵੀ ਕਾਲ ਕਹਿੰਦਾ ਹੈ ਕਿ ਤਦ ਇਹ ਕਥਾ ਪ੍ਰਸੰਗ ਸਮਾਪਤ ਹੋਇਆ ॥੫੨॥","meaning_pa_source":"BaniDB"}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ਸ੍ਰੀ ਚਰਿਤ੍ਰ ਪਖ੍ਯਾਨੇ ਤ੍ਰਿਯਾ ਚਰਿਤ੍ਰੇ ਮੰਤ੍ਰੀ ਭੂਪ ਸੰਬਾਦੇ ਦੋਇ ਸੌ ਸਤਰਹ ਚਰਿਤ੍ਰ ਸਮਾਪਤਮ","roman":"Iti sree charitr pakhyaane triyaa charitre mantree bhoop sanbaade doi sau satrah charitr samaaptam","meaning_en":"Thus ends the two hundred and seventeenth charitra of the Charitropakhyan, of the wiles of women, in the dialogue of the minister and the king; complete.","page":1891,"meaning_status":"draft","note":"The closing formula ਸਮਾਪਤਮ ਸਤੁ ਸੁਭਮ ਸਤੁ runs on into the next line."},{"gurmukhi":"ਸਤੁ ਸੁਭਮ ਸਤੁ। ੨੧੭। ੪੧੮੬। ਅਫਜੂੰ।","roman":"Satu subham satu | 217 | 4186 | aphjoon |","meaning_en":"True, auspicious, true. 217. 4186. It continues.","page":1891,"meaning_status":"draft","note":"ਸਤੁ ਸੁਭਮ ਸਤੁ: taken with ਸਮਾਪਤਮ of the previous line as 'may it be complete, may it be auspicious'; ਸਤੁ may also be read as 'true'. The second number is the running verse count. ਅਫਜੂੰ: Persian, 'more', i.e. the text continues.","meaning_pa":"ਇਥੇ ਸ੍ਰੀ ਚਰਿਤ੍ਰੋਪਾਖਿਆਨ ਦੇ ਤ੍ਰੀਆ ਚਰਿਤ੍ਰ ਦੇ ਮੰਤ੍ਰੀ ਭੂਪ ਸੰਵਾਦ ਦੇ ੨੧੭ਵੇਾਂ ਚਰਿਤ੍ਰ ਦੀ ਸਮਾਪਤੀ, ਸਭ ਸ਼ੁਭ ਹੈ ॥੨੧੭॥੪੧੮੬॥ ਚਲਦਾ॥","meaning_pa_source":"BaniDB","note_pa":"ਇਹ ਅਰਥ ਇਸ ਪੰਕਤੀ ਸਮੇਤ ਉੱਪਰਲੀਆਂ 2 ਪੰਕਤੀਆਂ ਦਾ ਇਕੱਠਾ ਹੈ।"}],"page":1891,"number":[217,4186]}});
